-- 0260 turismo_mascotas (inventario_turismo_mascotas_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04002','mascotas','Playa de la Rana','Destino con recurso de baño acotado de 350 metros lineales, suelo pedregoso y sin servicios premium como duchas caninas. Planta hotelera local limitada con suplementos por mascota de 15 €/noche. Registra un impacto moderado de turismo familiar de proximidad. La nota refleja la falta de equipamiento y restricciones de movilidad. Turismo con mascotas. Normativa: Ordenanza de Playas regula su uso exclusivo para mascotas todo el año. Prohibido el baño humano. Uso de correa obligatorio fuera del agua. Sanciones por no recogida de deyecciones de hasta 300 €. Transporte urbano restringe acceso a perros de más de 10 kg en transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','mascotas','Playa de El Bobar y Red de Autobuses Surbús','Núcleo urbano con accesibilidad en transporte público regulada positivamente. Cuenta con una densidad intermedia de restauración con terrazas accesibles y hoteles urbanos adaptados. La playa canina sufre de alta presencia de piedras y carece de vallado perimetral, lo que limita su puntuación pese al avance en movilidad. Normativa: Modificación de la Ordenanza de Transportes permite acceso de perros a autobuses urbanos con bozal y correa corta. Playa de El Bobar autorizada pero con restricciones de baño en época estival alta según directivas de la Junta. Alojamientos céntricos aplican límite general de 15 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04035','mascotas','Playa de Cala Verde (Pozo del Esparto)','Recurso natural aislado con baja masificación, ideal para turismo de aventura y pernoctación en casas rurales dispersas. Carece por completo de duchas caninas, papeleras específicas o conectividad peatonal segura. Su baja puntuación se debe a la ausencia de infraestructuras hoteleras consolidadas en el núcleo urbano. Normativa: Ordenanza municipal específica para el uso recreativo de calas escarpadas. Permite perros sueltos solo dentro de la zona delimitada de baño. Acceso a transportes Turismo con mascotas inexistente en el entorno rural. Alojamientos locales exigen fianza reembolsable por daños de hasta 100 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04008','mascotas','Parque Canino de Almerimar y Complejo AR Almerimar','Destino con excelente dotación de ocio privado. El Parque Canino de Almerimar ofrece más de 1.000 m² con circuito de agilidad y doble puerta de seguridad. El sector hotelero destaca por resorts vacacionales que permiten mascotas de tamaño medio y ofrecen zonas de paseo interiores. Alta densidad de restaurantes y gastrobares en el puerto deportivo que toleran perros en sus instalaciones. Normativa: Ordenanza de Convivencia Ciudadana autoriza mascotas en terrazas hosteleras sin restricciones. Acceso interior supeditado al derecho de admisión del local. El transporte público en la costa limita el acceso a perros de menos de 12 kg metidos en su transportín. Obligatorio el censado genético canino.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04016','mascotas','Alojamientos Rurales de Turre-Mojácar y Red de Senderos de Sierra Cabrera','Gran referente andaluz para el turismo de naturaleza con mascotas. Combina una planta de apartamentos turísticos de alta permisividad con una oferta gastronómica en el casco Turismo con mascotas histórico donde el 35% de los locales permiten la entrada de perros al interior. La oficina de turismo local distribuye una guía oficial con rutas y comercios adheridos al sello "Mojácar Pet-Friendly". Normativa: Normativa local pionera en turismo activo. Permite el tránsito libre de perros con correa en toda la red de senderos históricos. Los hoteles de la cadena local eximen del límite de peso en habitaciones seleccionadas (previa reserva). Queda prohibido el acceso de animales a las fuentes públicas bajo multa de 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','mascotas','Senderos del Parque Natural y Camping Los Escullos','Destino rústico y ecoturístico de alta demanda internacional. Destaca por infraestructuras de acampada e instalaciones hoteleras boutique que ofrecen servicios de lavado canino y zonas de sombra valladas. El núcleo urbano de San José concentra restaurantes que facilitan agua y menús específicos para mascotas en sus terrazas protegidas, compensando las restricciones ambientales de las calas. ¿Procedemos a auditar el siguiente bloque de la provincia de Almería, o prefiere saltar a la siguiente provincia en orden alfabético (Cádiz)?. Normativa: La normativa del PORN del Parque Natural prohíbe taxativamente que los perros vayan sueltos por los senderos para proteger la fauna local. Playas vírgenes no urbanas toleran la presencia de perros fuera de la temporada de baño oficial (junio a septiembre). El camping local no impone límites de peso en parcelas y zonas de acampada.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04023','mascotas','Parque Canino de Las Salinas y Alojamientos Protur Roquetas Hotel & Spa','Gran polo de turismo familiar que destaca por el Parque Canino de Las Salinas, un recinto vallado de 1.500 m² con equipamiento de Agility, zonas de sombra y fuentes adaptadas. La planta de aparthoteles de la zona residencial y el sector de restauración del paseo marítimo muestran un alto índice de aceptación en terrazas, ofreciendo recipientes de agua de cortesía de forma sistemática. Normativa: Ordenanza Reguladora de la Tenencia de Animales permite el acceso a locales comerciales con el distintivo visible en la entrada. Prohibido el baño de mascotas en playas urbanas durante la temporada estival (junio a septiembre), acarreando multas de hasta 400 €. Autobuses del Consorcio de Transportes exigen transportín rígido obligatorio.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04029','mascotas','Zona de Esparcimiento Canino El Palmeral y Complejo Vera Playa Club Hotel','Destino costero con un desarrollo urbanístico que favorece el paseo en espacios abiertos. Destaca el área canina de El Palmeral, dotada de doble compuerta de seguridad y suelo de arena fina. Los chiringuitos de la zona norte de la playa de Puerto Rey permiten el libre acceso de perros en sus áreas de restauración sombreadas, lo que equilibra la restricción de baño en la arena. [1, 2]. Normativa: La normativa municipal sanciona severamente la no recogida de deyecciones (hasta 500 €) e impone el uso de correa extensible a un máximo de 2 metros en vías públicas. No se permite el acceso a los arenales urbanos en época de baño alta. Los hoteles del litoral aceptan mascotas bajo petición con un suplemento fijo de 20 € por estancia.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04006','mascotas','Red de Establecimientos del Casco Urbano y Rutas de Senderismo de Mesa Roldán','Municipio enfocado al turismo activo de naturaleza. Aunque las playas del núcleo urbano son restrictivas, el entorno de Mesa Roldán ofrece senderos paisajísticos idóneos para el senderismo canino. La hostelería del centro histórico cuenta con una densidad moderada de bares de tapas y cafeterías que admiten perros en el interior de sus instalaciones durante los meses de invierno y primavera. Normativa: Ordenanza municipal estricta respecto al uso de playas en Turismo con mascotas temporada alta (prohibición absoluta en arenales urbanos). Permite el tránsito por senderos naturales periféricos siempre con correa. Los taxis locales aceptan perros medianos si el propietario aporta una manta protectora para los asientos.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04013','mascotas','Parque Canino Adolfo Suárez y Alojamientos de Turismo Rural del Bajo Almanzora','Punto de conexión interior para el turismo que busca tranquilidad y rutas rurales. El Parque Canino Adolfo Suárez es el principal recurso del municipio, equipado con bebederos automáticos y circuitos de saltos bien mantenidos. La oferta de restauración interior está muy limitada al derecho de Turismo con mascotas admisión, concentrando la actividad pet-friendly exclusivamente en las terrazas exteriores de las plazas principales. Con este bloque finaliza el análisis técnico y de infraestructuras de la provincia de Almería. Normativa: Normativa local de tenencia orientada a entornos urbanos de interior. Obligatoriedad de portar botella de agua con detergente para limpiar las micciones caninas en fachadas y mobiliario urbano, bajo riesgo de sanción de 150 €. Alojamientos rurales exigen el uso de transportín si la mascota se queda sola en la habitación.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16002','mascotas','Playa de la Concha (El Rinconcillo) y Parque Canino del Humedal','Destino costero e industrial con infraestructuras en expansión. La playa de La Concha cuenta con arena fina y aguas tranquilas, equipada con papeleras específicas pero carece de duchas caninas de agua dulce. El Parque del Humedal ofrece un espacio verde amplio vallado de 1.200 m². Los hoteles urbanos de la periferia aceptan perros de hasta 20 kg cobrando un suplemento de 12 €/noche. Normativa: Ordenanza de Playas habilita un tramo acotado en la zona de La Concha exclusivamente para el baño canino durante todo el año. Uso de correa obligatorio para el acceso a la zona de arena. Sanciones de hasta 300 € por no recogida de excrementos. El transporte urbano limita el acceso a perros en transportín. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90031','mascotas','Playa Canina de Zahara de los Atunes y Parque Natural de La Breña','Enclave turístico de gran relevancia internacional para el turismo de naturaleza y playa. El tramo autorizado es de arena virgen fina y cuenta con señalización excelente. El sector de apartamentos turísticos locales no impone límite de peso en el 40% de su oferta, cobrando fianzas mínimas. Alta concentración de terrazas gastronómicas que ofrecen recipientes de agua de cortesía de forma sistemática. Normativa: Ordenanza municipal regula el tramo de playa canina colindante con el término de Tarifa. En el Parque Natural de La Breña los perros deben transitar estrictamente atados para proteger la avifauna. Los chiringuitos de la zona de Los Caños de Meca y Zahara muestran una de las normativas de admisión interna más laxas de la provincia.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','mascotas','Tramo Canino de la Playa de Cortadura y Red de Autobuses Urbanos','Núcleo urbano histórico con alta densidad de comercio local y restauración que permite el acceso interior de perros educados. La planta hotelera del paseo marítimo ofrece habitaciones adaptadas pero con límites de peso estrictos (generalmente bajo los 12 kg). Destaca la concienciación ciudadana y la accesibilidad peatonal, aunque penaliza la restricción estival de su principal playa. Normativa: Modificación reciente de la ordenanza de playas permite el acceso de perros a una zona delimitada de Cortadura exclusivamente fuera de la temporada alta (restringido de junio a septiembre). Los autobuses urbanos permiten mascotas de hasta 15 kg siempre que viajen en transportín homologado. Obligatorio el uso de limpiador de orina con agua y vinagre.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90032','mascotas','Playa Canina de Montijo-Niño de Oro y Alojamientos Rurales Periféricos','Destino costero tradicional con una infraestructura pet-friendly concentrada en su periferia. La playa de Montijo es de carácter rocoso, con fuerte oleaje y accesibilidad moderada, careciendo de servicios como duchas o pasarelas de acceso adaptadas. El impacto del turismo familiar con mascotas se concentra en chalets de alquiler íntegro y campings de los alrededores que admiten perros sin límite de peso. Normativa: Ordenanza de Playas prohíbe taxativamente la presencia de perros en las playas urbanas (Regla, Cruz del Mar) durante todo el Turismo con mascotas año, derivando el uso al tramo natural de Montijo. Sanciones graves de hasta 600 € por incumplimiento. Los hoteles del centro urbano muestran reticencia al acceso canino, limitándose mayoritariamente a terrazas exteriores.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16008','mascotas','Calas de Roche (zonas no reguladas) y Complejo Fuerte Conil-Resort','Destino de gran afluencia estival que equilibra la restricción de playas urbanas con una oferta hostelera privada de primer nivel. Cuenta con una gran cantidad de restaurantes con patios interiores y terrazas amplias donde las mascotas son bienvenidas. El Turismo con mascotas turismo residencial en urbanizaciones periféricas fomenta una alta ocupación de familias con perros medianos y grandes. Normativa: La ordenanza prohíbe el baño de perros en los arenales principales en temporada alta, provocando el desplazamiento a calas de difícil acceso. Los hoteles de gran categoría del municipio cuentan con programas específicos ("Doggy Guest") que permiten perros de hasta 15 kg, incluyendo cama, comedero y obsequio de bienvenida. Sanciones severas por llevar perros sueltos en el casco histórico (hasta 300 €).','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11027','mascotas','Playa Canina de Fuentebravía (Litoral Oeste) y Parque del Vino Fino','Importante nodo enoturístico y costero. La zona de esparcimiento del Parque del Vino Fino cuenta con equipamiento ágil y áreas sombreadas de gran extensión. Las bodegas locales están comenzando a adaptar sus rutas turísticas para permitir el acceso de perros atados, potenciando el turismo cultural. El sector de la restauración en Puerto Sherry destaca por su flexibilidad y acogida en áreas exteriores cubiertas. Normativa: La ordenanza municipal de playas reserva un espacio delimitado de 400 metros para el uso canino estival con servicios básicos. Obligatorio mantener al perro con correa en la arena y solo soltarlo dentro del agua. Los taxis locales muestran una alta tasa de aceptación bajo aviso previo. Los hoteles del centro histórico limitan el peso a 10 kg por mascota.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11030','mascotas','Playa Canina de Peginas y Parque Laguna del Moral','Uno de los destinos costeros mejor valorados de la provincia por su infraestructura pública. La playa canina de Peginas goza de excelentes accesos y mantenimiento diario del arenal. El Parque Laguna del Moral incluye un pipicán de grandes dimensiones con doble puerta y juegos de agilidad bien conservados. Los complejos hoteleros de Costa Ballena cuentan con normativas muy integradoras que permiten la convivencia armónica de los huéspedes. ¿Procedemos a auditar el siguiente bloque de la provincia de Cádiz (Municipios de la S a la Z, incluyendo Tarifa y Sanlúcar). Normativa: Ordenanza de Playas vanguardista que habilita un espacio permanente en la Playa de Peginas dotado de pasarelas de madera, ducha específica para perros y fuentes adaptadas. Los perros de asistencia y domésticos educados tienen acceso permitido a edificios públicos municipales bajo control. Sanción por micciones no diluidas de 75 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11031','mascotas','Playa de la Casería, Playa Canina de Camposoto y Parques de Esparcimiento','Gran referente andaluz en infraestructuras de litoral. La playa canina de Camposoto es considerada una de las mejor equipadas de España; cuenta con duchas caninas de agua dulce, fuentes adaptadas a doble altura, mangueras de limpieza y papeleras de reciclaje específicas. El municipio complementa esto con más de cinco parques urbanos dotados de amplias zonas de esparcimiento canino (pipicanes con Agility) y una red comercial local con alta tolerancia al acceso interior. Normativa: Ordenanza municipal pionera que regula un extenso tramo vallado en la Playa de Camposoto accesible durante la temporada estival alta. Acceso peatonal habilitado mediante una pasarela específica de madera (acceso 8). Obligatorio el uso de correa hasta el recinto acotado. Acceso a transportes públicos limitado a mascotas en transportín de dimensiones reducidas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','mascotas','Playas del Litoral de Bonanza y Alojamientos Históricos del Centro','Destino gastronómico de primer orden que flexibiliza su oferta en el sector privado. Aunque las playas principales sufren restricciones severas en verano, la zona de Bajo de Guía cuenta con una gran densidad de terrazas de restauración que facilitan agua y espacio para mascotas. La planta hotelera y de apartamentos turísticos de la zona monumental permite la pernoctación de perros de tamaño pequeño y mediano (hasta 15 kg), aplicando por lo general tarifas de limpieza fijas de entre 10 € y 15 € por estancia. Normativa: Queda estrictamente prohibido el acceso y permanencia de animales de compañía en las playas urbanas (Bajo de Guía, Calzada y Las Piletas) durante la temporada de baño (de junio a septiembre). Se permite el paseo con correa en las playas de entorno natural como Bonanza. Las terrazas hosteleras operan bajo libre derecho de admisión, con un porcentaje intermedio de locales tolerantes.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11033','mascotas','Playa Canina de Torreguadiaro (Los Marrajos) y Urbanización Sotogrande','Destino de turismo residencial y deportivo de alto poder adquisitivo. La playa para perros ofrece un espacio natural limpio, dotado de contenedores específicos y señalización clara, aunque el suelo combina arena con pequeños guijarros. El puerto deportivo de Sotogrande destaca por su alta tolerancia en el sector de la restauración, donde múltiples cafeterías y locales comerciales permiten la entrada de perros educados al interior de sus instalaciones. Normativa: Ordenanza de Playas regula un espacio exclusivo para perros en la zona de Alcaidesa-El Faro y Torreguadiaro. Obligatorio mantener el control visual de la mascota y portar la documentación sanitaria en regla. Las sanciones por no recoger deyecciones oscilan entre los 150 € y los 600 €. Los hoteles de gran lujo de Sotogrande limitan el acceso Turismo con mascotas por zonas comunes pero permiten mascotas bajo reserva previa.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','mascotas','Playa Canina de Los Lances (zona norte regulada) y Alojamientos Ecoturísticos','Uno de los epicentros del turismo joven y deportivo con mascotas en el sur de Europa. Cuenta con la mayor densidad por metro cuadrado de hoteles boutique, campings tipo ''glamping'' y apartamentos turísticos que no discriminan por raza ni peso. Prácticamente el 60% de los bares, cafeterías y tiendas de moda del centro permiten el acceso interior de Turismo con mascotas mascotas, proporcionando espacios cómodos y adaptados que contrarrestan las regulaciones ambientales de sus playas protegidas. Normativa: La normativa municipal restringe la presencia de perros sueltos en las zonas de mayor afluencia de bañistas y escuelas de kitesurf durante los meses centrales de verano, habilitando tramos específicos en el entorno natural. Alta permisividad en alojamientos, campings y hostales donde abundan las políticas sin límite de peso. Obligatorio el uso de correa en todo el casco histórico amurallado.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','mascotas','Alojamientos Rurales de El Palmar y Rutas de Senderismo de las Breñas','Núcleo monumental de interior con una fuerte extensión costera en El Palmar. Es un destino muy demandado por el turismo que viaja con perros gracias a su oferta de casas rurales independientes y escuelas de surf con mentalidad integradora. Las escuelas de surf y los conocidos "surf camps" disponen de recintos y zonas comunes diseñadas para la estancia de mascotas. La hostelería del casco histórico amurallado ofrece patios interiores climatizados aptos para el disfrute en familia con el perro. Con este bloque finaliza la auditoría de la provincia de Cádiz. Turismo con mascotas ¿Procedemos a iniciar de forma masiva la provincia de Córdoba, continuando el orden alfabético global de Andalucía? Elige una opción si deseas continuar: • Continuar con la provincia de Córdoba (Municipios de interior y embalses). Normativa: Prohibición absoluta de perros en la arena de la playa de El Palmar durante el día en época estival (sujeto a multas de hasta 300 €). Se permite el tránsito por el paseo marítimo peatonal y los senderos colindantes siempre que el animal vaya atado. Flexibilidad absoluta en las ordenanzas para el establecimiento de terrazas y espacios gastronómicos al aire libre.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17002','mascotas','Embalse de La Breña y Entorno del Castillo de Almodóvar','Destino de interior clave que ofrece una alternativa sólida al turismo de costa gracias a su playa continental apta para mascotas. Cuenta con una oferta de turismo activo (alquiler de canoas y senderismo) altamente tolerante. Los alojamientos rurales de los alrededores aceptan animales de todos los tamaños, facilitando amplias parcelas valladas, aunque la planta hotelera del núcleo urbano consolidado mantiene limitaciones de peso estrictas. Normativa: Ordenanza municipal regula el uso de la playa de interior en el embalse de La Breña, delimitando una zona de baño exclusiva para perros. Uso de correa obligatorio en el entorno perimetral del embalse y accesos. El monumento histórico del Castillo permite el acceso de perros de hasta 10 kg en brazos o transportín en zonas seleccionadas. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','mascotas','Red de Parques Caninos (Parque Cruz Conde, Vial Norte) y Red de Autobuses AUCORSA','Gran referente nacional para el turismo cultural e histórico con mascotas. Cuenta con un tejido de parques urbanos excelente, destacando las zonas de esparcimiento canino de Cruz Conde y El Patriarca, que superan los 1.500 m² con circuitos de agilidad completos. El 35% de los hoteles urbanos del centro histórico ofrece servicios específicos para perros (camas y comederos) sin límite de peso en categorías seleccionadas. Los patios cordobeses y terrazas de la Turismo con mascotas judería muestran un índice de aceptación interior muy elevado. Normativa: La ordenanza municipal de transportes permite el acceso de perros a los autobuses urbanos siempre que viajen en transportín homologado. Obligatoriedad estricta de diluir las micciones caninas con agua y vinagre en la vía pública bajo multas de hasta 150 €. Alta densidad de establecimientos comerciales y hoteleros del casco antiguo que admiten mascotas bajo políticas reguladas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14037','mascotas','Playa de Valdearenas (Embalse de Iznájar) y Senderos del Parque Natural de las Sierras Subbéticas','Enclave de gran atractivo estival para el turismo interior. La playa canina de Valdearenas dispone de un entorno de arena fina y aguas tranquilas, rodeado de pinares con zonas de sombra naturales muy valoradas por los usuarios. El municipio fomenta el turismo con perros a través de sus rutas de senderismo adaptadas y un sector de restauración local en el entorno del lago que facilita el acceso a terrazas sombreadas con bebederos de cortesía. Normativa: Ordenanza de uso del embalse regula una de las playas fluviales petfriendly más grandes de Andalucía. Permite el baño libre de las mascotas dentro del área balizada todo el año. Fuera del agua se exige el uso de correa y control visual constante. Las casas de turismo rural de la comarca exigen suplementos variables que rondan los 10 € por noche y mascota.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','mascotas','Zona de Esparcimiento Canino de la Avda. de España y Alojamientos Rurales de la Subbética Turismo con mascotas','Destino monumental de interior cuya oferta pet-friendly descansa principalmente en el alojamiento rural integrado en la naturaleza. El municipio dispone de un parque canino acotado con elementos de juego básicos en el núcleo urbano. La restauración destaca por una excelente acogida en los patios interiores de los restaurantes tradicionales, donde los perros son bienvenidos, facilitando la conciliación del turismo gastronómico familiar. Con este bloque completamos los núcleos de mayor relevancia e infraestructura consolidada de la provincia de Córdoba. ¿Procedemos a iniciar de forma masiva la auditoría de la provincia de Granada, continuando el orden alfabético de Andalucía? Elige una opción si deseas continuar: • Continuar con la provincia de Granada (Costa Tropical y Sierra Nevada). Normativa: Normativa local enfocada a la protección del patrimonio barroco. Prohibido el acceso de mascotas a monumentos religiosos y fuentes históricas monumentales. Uso de correa obligatorio de un máximo de 1,5 metros en todo el casco histórico. Los alojamientos rurales independientes de la periferia muestran flexibilidad total, mientras que las opciones del centro urbano aplican límites estrictos de peso (hasta 10 kg).','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19002','mascotas','Playa Canina de El Cable (Playa de Cantarriján en entorno natural) y Paseo Fluvial','Importante núcleo turístico de la Costa Tropical. La playa canina cuenta con una longitud moderada de suelo mixto (arena gruesa y guijarros) y está equipada con papeleras específicas, aunque carece de duchas caninas de agua dulce de uso exclusivo. Los chiringuitos de los paseos marítimos de Velilla y San Cristóbal muestran una alta tolerancia en Turismo con mascotas terrazas exteriores, facilitando recipientes de agua de cortesía. Los apartamentos turísticos vacacionales constituyen el grueso de la oferta hotelera sin límite de peso. Normativa: La Ordenanza Municipal de Playas habilita un tramo acotado en la Playa de El Cable (junto a la desembocadura del río Verde) para el acceso con mascotas durante todo el año. Uso obligatorio de correa en los accesos de arena. Se imponen sanciones de hasta 300 € por micciones no diluidas en mobiliario urbano. El transporte en autobuses locales limita el acceso a mascotas pequeñas en transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','mascotas','Red de Parques Caninos (Parque Tico Medina, Federico García Lorca) y Alojamientos Céntricos','Gran polo de turismo cultural y universitario con una excelente infraestructura verde urbana. Destaca de forma sobresaliente el Parque Tico Medina, considerado uno de los mayores espacios de esparcimiento canino de Andalucía, con más de 3.000 m² acotados, zonas de juego ágil y fuentes de doble nivel. Los hoteles boutique del centro histórico y el Albaicín ofrecen programas adaptados que aceptan perros de hasta 15-20 kg. El sector de la restauración destaca por una excelente oferta de bares de tapas con patios interiores y terrazas muy integradoras. Normativa: La normativa de transporte metropolitano restringe el acceso de mascotas al metro ligero (salvo perros guía o perros pequeños en transportín cerrado). Obligatoriedad estricta de censado por ADN canino y portar botella de agua con detergente para limpiar micciones bajo multas de hasta 150 €. Alta densidad de comercios en el centro y barrio del Realejo adheridos a políticas de acceso interior.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18134','mascotas','Estación de Esquí de Sierra Nevada y Senderos de Los Cahorros','Destino internacional de turismo de nieve y turismo activo de montaña. Destaca la ruta de senderismo de Los Cahorros, un cañón natural de alta demanda donde los excursionistas viajan de forma masiva con sus perros (requiere precaución en los puentes colgantes). La planta de apartamentos turísticos de alquiler vacacional y los hoteles de ambiente alpino registran una de las tasas de aceptación de mascotas más altas de la provincia. Los restaurantes de Pradollano cuentan con amplias terrazas adaptadas con calefactores exteriores ideales para el descanso familiar. Normativa: La normativa del Parque Nacional de Sierra Nevada obliga a mantener a los perros con correa en todos los senderos protegidos para evitar la alteración de la fauna silvestre. En la urbanización de Pradollano (estación de esquí), los remontes principales prohíben el acceso de animales (salvo perros de asistencia). Los hoteles de alta montaña muestran políticas muy flexibles sin límites de peso estrictos pero exigen suplementos de limpieza de unos 15-20 €/noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18140','mascotas','Playa Canina de Playa Granada y Complejo Camping Playa de Poniente','Enclave costero con una playa canina de excelente mantenimiento, suelo de arena fina combinada con piedras y equipada con pasarelas de acceso y contenedores específicos. El entorno de Playa Granada destaca por su desarrollo residencial moderno, lo que fomenta el turismo familiar de larga estancia con mascotas. El sector de la restauración en la Playa de Poniente cuenta con chiringuitos muy habituados a dar servicio a clientes con perros, ofreciendo áreas de sombra confortables. Con este bloque cubrimos los puntos neurálgicos y de mayor densidad turística de la provincia de Granada. ¿Procedemos a iniciar de forma masiva la auditoría de la provincia de Huelva, continuando el orden alfabético de Andalucía? Elige una opción si deseas continuar: • Continuar con la provincia de Huelva (Playas del Atlántico y Sierra de Aracena). Normativa: Ordenanza de Playas pionera en la provincia al reservar un tramo permanente en la zona de Playa Granada. Está permitido el baño de mascotas y la permanencia sin correa exclusivamente dentro del recinto delimitado. Queda totalmente prohibido el tránsito de perros sueltos por los paseos marítimos urbanos. Los hoteles de la zona aplican un límite de peso medio fijado en los 12 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22006','mascotas','Playa Canina de Isla Canela (Los Haraganes) y Red de Transbordadores del Guadiana','Destino fronterizo de alta relevancia turística internacional. La playa para perros cuenta con una gran extensión de arena blanca y fina, aguas tranquilas ideales para el baño y equipamiento básico de papeleras. La planta de apartamentos turísticos de Isla Canela destaca por una flexibilidad elevada, donde más del 35% de los alojamientos aceptan perros grandes sin límite de peso. Los restaurantes del puerto deportivo facilitan terrazas amplias y sombreadas de gran aceptación. Normativa: La Ordenanza Municipal de Playas regula de forma permanente una zona canina oficial en el tramo de Los Haraganes. Los animales deben permanecer con correa hasta entrar en la zona delimitada. El transbordador fluvial que conecta con Portugal permite el acceso de mascotas atadas y con bozal. Sanciones por no recogida de deyecciones de hasta 400 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','mascotas','Playa Canina del Espigón y Parque de Zafra','Núcleo urbano que destaca por su inmenso recurso de litoral salvaje en el Espigón, dotado de un área canina de más de 2.500 metros de longitud de arena fina, ideal para el esparcimiento masivo, aunque carece de duchas de agua dulce por su condición natural. En el centro de la ciudad, el Parque de Zafra ofrece una zona de esparcimiento vallada de 1.200 m² con equipamiento básico. Los hoteles céntricos enfocados al turismo de negocios y cultural aceptan mascotas bajo un límite medio de 15 kg. Normativa: El Ayuntamiento autoriza de manera permanente el acceso de mascotas a las pasarelas 5 y 6 de la Playa del Espigón (dentro del paraje natural Marismas del Odiel). Obligatorio el uso de correa en todo el entorno protegido por normativas ambientales andaluzas. La ordenanza de transporte urbano restringe el acceso de mascotas en autobuses a perros de tamaño pequeño dentro de su transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21042','mascotas','Playa Canina de Icona (Playa de El Cantil) y Camping Giralda','Enclave pesquero y turístico muy demandado por el turismo familiar con mascotas. La playa autorizada cuenta con un entorno natural rodeado de dunas y pinares, proporcionando sombra natural, aunque el arenal puede presentar restos de conchas y vegetación marina según las mareas. Los chiringuitos locales muestran una tolerancia intermedia, concentrando el acceso de perros exclusivamente en las mesas periféricas de sus terrazas exteriores. Normativa: Ordenanza de uso de playas reserva el tramo de Icona-Playa Central para el disfrute con mascotas. Está totalmente prohibida la presencia de perros sueltos en los arenales urbanos principales durante la temporada estival alta (junio a Turismo con mascotas septiembre). El camping local aplica una política flexible admitiendo perros en parcelas pero restringiendo razas catalogadas como potencialmente peligrosas (PPP) por normativa autonómica.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21050','mascotas','Playa Canina de las Casas de Bonares (Mazagón) y Senderos del Entorno de Doñana','Destino costero salvaje idóneo para el turismo de naturaleza y desconexión en pareja con mascota. La playa canina ofrece un paisaje espectacular de acantilados arenosos, suelo de arena Turismo con mascotas fina y gran extensión para correr, aunque carece de servicios públicos urbanos como lavapiés caninos o fuentes. El sector de la restauración en el puerto deportivo de Mazagón muestra una aceptación consolidada en terrazas exteriores, facilitando cuencos con agua limpia. Normativa: Habilitado un tramo específico en el sector costero de Mazagón administrado por el municipio de Moguer. Normas ambientales estrictas debido a la proximidad del Espacio Natural de Doñana: prohibido rotundamente que los perros transiten sueltos por los acantilados o dunas protegidas. Los hoteles y complejos de apartamentos de la zona costera exigen por lo general un suplemento diario de entre 10 € y 15 € por mascota.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','mascotas','Red de Senderos de la Sierra de Aracena y Picos de Aroche y Alojamientos Rurales','Uno de los grandes referentes del turismo rural de interior en España. Destaca por una planta masiva de casas rurales independientes, cortijos y hoteles boutique de campo que no imponen ningún tipo de límite de peso o raza, ofreciendo fincas valladas ideales para el disfrute animal. El centro histórico de Aracena cuenta con una alta densidad de mesones y restaurantes tradicionales con patios empedrados donde se permite comer acompañado de la mascota de forma habitual. Turismo con mascotas Con este bloque completamos la auditoría de los municipios costeros y de montaña más representativos de la provincia de Huelva. ¿Procedemos a iniciar de forma masiva la auditoría de la provincia de Jaén, continuando el orden alfabético de Andalucía? Elige una opción si deseas continuar: • Continuar con la provincia de Jaén (Parques Naturales, Cazorla y Ciudades Úbeda/Baeza). Normativa: Normativa del Parque Natural permite el tránsito de perros por la red oficial de senderos históricos siempre que vayan bajo control y con correa si se cruzan con ganado extensivo. Prohibido el acceso de mascotas al interior del monumento natural de la Gruta de las Maravillas. Las ordenanzas locales eximen de tasas de estancia a perros de asistencia.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','mascotas','Paseo de la Constitución y Alojamientos Monumentales TRH Ciudad de Baeza','Ciudad Patrimonio de la Humanidad con un urbanismo peatonal idóneo para pasear con perros. Cuenta con hoteles instalados en antiguos conventos y casas palacio que aceptan mascotas cobrando suplementos de unos 12 €/noche. El sector de la restauración destaca por sus tabernas tradicionales con patios castellanos interiores donde se permite el acceso con mascotas, facilitando el tapeo familiar de forma segura y confortable. Normativa: Ordenanza de Convivencia protege el entorno monumental; prohibido el acceso de perros sueltos o el uso de fuentes históricas por animales bajo multas de hasta 200 €. Obligatorio el uso de azufradores o botellas con agua jabonosa para limpiar micciones. Los hoteles del centro histórico limitan el peso a un promedio de 15 kg por mascota.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','mascotas','Senderos del Parque Natural y Alojamientos del Casco Viejo','Uno de los grandes epicentros españoles de turismo activo y de naturaleza con mascotas. Sirve como puerta de entrada a rutas de senderismo masivas como la Cerrada del Utrero o el nacimiento del río Guadalquivir. La planta alojativa local está hiperespecializada en familias con perros, ofreciendo patios amplios o fincas valladas. Los restaurantes de la Plaza de la Corredera disponen de terrazas climatizadas totalmente adaptadas para el descanso tras las rutas. Normativa: La normativa de la Junta de Andalucía para Parques Naturales exige llevar a los perros con correa en zonas de reserva para evitar molestias a la fauna salvaje (cabra montés, ciervos) y al ganado. Alta permisividad en los alojamientos del municipio, eliminando el límite de peso en el 50% de las casas rurales. Sanciones de hasta 300 € por dejar mascotas sueltas sin control. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','mascotas','Parque del Bulevar (Zonas de Esparcimiento) y Hotel Condestable Iranzo','Núcleo urbano de interior en proceso de expansión de servicios. Su principal recurso es el Parque del Bulevar, que cuenta con una amplia zona acotada para el esparcimiento canino con elementos de Agility bien mantenidos. La planta hotelera del centro administrativo acepta mascotas bajo petición previa y suplemento. La restauración muestra una aceptación consolidada en terrazas exteriores, aunque el Turismo con mascotas acceso al interior de locales sigue sujeto a un estricto derecho de admisión. Normativa: Ordenanza Municipal reguladora de la Tenencia de Animales prohíbe el acceso de perros a parques infantiles y jardines no señalizados. Los autobuses urbanos limitan el acceso exclusivamente a perros de asistencia y mascotas pequeñas en transportín homologado. Obligatorio el registro en el censo genético municipal de ADN canino.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','mascotas','Red de Alojamientos del Centro Histórico y Plaza de Vázquez de Molina','Destino cultural complementario a Baeza. Destaca por una oferta hotelera boutique que ofrece kits de bienvenida para perros (manta, comedero y snacks). El turismo familiar con mascotas se beneficia de plazas peatonales muy amplias y despejadas. Los establecimientos de restauración y cafeterías del entorno de la Calle Real muestran una mentalidad abierta, permitiendo la presencia de perros educados tanto en terrazas como en zonas de barra interiores. Con este bloque finaliza la auditoría de los puntos clave con mayor densidad de servicios de la provincia de Jaén. Turismo con mascotas ¿Procedemos a iniciar de forma masiva la auditoría de la provincia de Málaga, continuando el orden alfabético de Andalucía? Elige una opción si deseas continuar: • Continuar con la provincia de Málaga (Costa del Sol, Playas Caninas y Capital). Normativa: Normas locales estrictas respecto a la limpieza en el casco antiguo monumental: multas de hasta 300 € por deyecciones no retiradas o micciones en fachadas históricas. Tránsito obligatorio con correa de longitud máxima de 1,5 metros. Hoteles de alta gama permiten mascotas aplicando tarifas fijas de limpieza (entre 15 € y 20 € por estancia).','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','mascotas','Playa Canina de Arroyo Hondo (Playa de Carvajal) y Parque de la Paloma','Destino costero de alta relevancia. Su playa para mascotas ofrece un suelo de arena fina combinada con grava y está equipada con papeleras y señalización clara. El Parque de la Paloma destaca por sus extensas praderas verdes, aunque los perros deben transitar atados por caminos perimetrales. Los apartamentos turísticos del puerto deportivo muestran una flexibilidad total, eliminando el límite de peso en el 35% de su planta alojativa. Normativa: La Ordenanza Municipal de Playas habilita un tramo oficial en Arroyo Hondo operativo todo el año. Uso obligatorio de correa en los accesos de arena. Sanciones de hasta 500 € por no recogida de excrementos. El transporte en el autobús urbano local está restringido a perros pequeños dentro de su transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','mascotas','Playa Canina de la Sal y Alojamientos Rurales de interior','Municipio singular que conecta un casco histórico blanco de montaña con un pequeño tramo litoral. Su playa para mascotas destaca por un mantenimiento higiénico diario excelente y aguas Turismo con mascotas cristalinas, estando equipada con una ducha canina adaptada de agua dulce. La restauración del paseo marítimo colindante es muy tolerante y facilita recipientes de agua de cortesía de forma sistemática en sus terrazas. Normativa: Ordenanza específica regula un tramo de 400 metros de longitud en la Playa de la Sal. Se permite el baño libre de los animales y la permanencia sin correa exclusivamente dentro del recinto acotado. Normas locales obligan a portar la cartilla sanitaria al día. Transporte público inexistente para mascotas de gran tamaño.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29051','mascotas','Playa Canina de El Piedra Paloma y Red de Parques de Esparcimiento','Importante nodo residencial y vacacional. La playa canina ofrece un entorno natural espacioso de suelo mixto (arena gruesa y piedras) dotado de contenedores específicos. El municipio cuenta con áreas de esparcimiento canino valladas en los parques del núcleo urbano equipadas con juegos de Agility. El sector hotelero de lujo de la periferia acepta mascotas aplicando suplementos fijos de limpieza que oscilan entre los 20 € y 30 € por estancia. Normativa: Habilitado un tramo permanente en la zona colindante con Casares (Playa de El Piedra Paloma). Prohibido terminantemente que las mascotas pisen los arenales urbanos principales (La Rada o El Cristo) durante la temporada alta estival bajo multas de hasta 300 €. Los taxis locales muestran una aceptación intermedia bajo aviso previo del cliente.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29054','mascotas','Playa Canina del Castillo (Playa de El Castillo Sohail) y Parque Canino Guau Guau Turismo con mascotas','Icono mundial indiscutible del turismo con mascotas. Su playa canina junto al Castillo Sohail está considerada una de las mejores de Europa: cuenta con vallas perimetrales de seguridad, múltiples duchas caninas de agua dulce, fuentes a doble nivel, pasarelas de madera adaptadas y servicio de limpieza reforzado. El Parque Canino Guau Guau y el Parque Guau Guau 2 suman miles de metros cuadrados de césped, zonas de sombra y circuitos de Agility profesionales de uso libre. Más del 45% de la planta hotelera y un volumen masivo de restaurantes permiten el acceso al interior, consolidando un ecosistema urbano totalmente adaptado. Normativa: Ordenanza de Playas hiperpermisiva que regula una zona canina premium de más de 3.000 m² abierta los 365 días del año. Los perros pueden estar sueltos tanto en la arena acotada como en el agua. El Ayuntamiento exime de tasas de acceso y fomenta la integración. Los autobuses urbanos permiten el acceso de perros de todos los tamaños siempre que lleven bozal y correa corta.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','mascotas','Playa Canina de San Julián (Guadalmar), Playa Canina de Arroyo Totalán y Red de Autobuses EMT','Gran capital cultural con una conectividad de transporte inigualable en el sur de España. Dispone de dos amplios recursos de litoral: la playa de Guadalmar (zona de San Julián) y la playa de Arroyo Totalán (en el límite con Rincón de la Victoria), ambas equipadas con servicios básicos de papeleras y duchas para perros. La ciudad cuenta con una inmensa red de parques con pipicanes de grandes dimensiones y una planta de hoteles urbanos boutique de alta gama que eliminan el límite de peso y ofrecen camas caninas y comederos en la habitación de forma sistemática. Con este bloque cubrimos la capital y la zona occidental costera de mayor densidad. ¿Procedemos a continuar de forma masiva con el Bloque 2 de la provincia de Málaga (Costa del Sol Oriental, Marbella, Torremolinos, Nerja y Antequera). Normativa: La Ordenanza Municipal de Transportes de la EMT Málaga permite el acceso de perros a todas las líneas urbanas con bozal y correa, previo pago de billete infantil y obtención de tarjeta canina municipal. Obligatoriedad estricta de censado por ADN canino y portar botella de agua con jabón para limpiar micciones bajo multas de 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29069','mascotas','Playa Canina de El Pinillo, Playa Canina de Ventura de Mar y Complejo Don Carlos Resort','Destino de lujo internacional con servicios de alta gama. La playa canina de El Pinillo cuenta con 250 metros lineales equipados con duchas caninas de agua dulce, fuentes adaptadas y pasarelas de madera. La planta hotelera de cinco estrellas y resorts del municipio lidera las políticas sin límite de peso, ofreciendo servicios de conserjería canina, menús específicos y áreas de paseo exclusivas, compensando las restricciones en los paseos marítimos del centro urbano. Normativa: Ordenanza de Playas regula dos zonas caninas permanentes bien delimitadas. Prohibido el tránsito de mascotas sueltas por las playas urbanas del centro (La Fontanilla, Puerto Banús) durante la temporada estival alta, bajo multas de hasta 400 €. Los taxis locales muestran un índice de aceptación elevado bajo petición previa.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29075','mascotas','Playa Canina de Torrox-Nerja (Río Patamalara) y Alojamientos de la Axarquía Turismo con mascotas','Polo de atracción turística internacional adaptado principalmente en su oferta de alojamiento privado. Destaca por una gran cantidad de villas y apartamentos turísticos en acantilados y zonas residenciales periféricas con alta tolerancia hacia mascotas grandes. La restauración del centro histórico muestra una aceptación intermedia en terrazas exteriores, facilitando cuencos de agua limpia, aunque el acceso interior se ve penalizado por el derecho de admisión generalizado. Normativa: Ordenanza municipal prohíbe de forma taxativa el acceso de animales a los arenales más turísticos e icónicos (Burriana, Calahonda) durante todo el año. Se permite el acceso al tramo natural compartido en la desembocadura del río. El uso de correa es obligatorio en todo el casco histórico y en el entorno del Balcón de Europa.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29082','mascotas','Playa Canina de Torre del Benagalbón y Parques Urbanos de Esparcimiento','Municipio costero de perfil residencial familiar. Su playa canina ofrece un entorno espacioso de arena fina y grava, dotado de valla perimetral de seguridad, papeleras de reciclaje y mangueras de limpieza. Los restaurantes y chiringuitos de la zona este muestran una de las normativas de admisión en terrazas exteriores más flexibles de la comarca de la Axarquía, registrando un fuerte impacto de turismo de proximidad con mascotas. Normativa: Ordenanza específica habilita de forma permanente un tramo de litoral en Torre del Benagalbón. Sanciones de hasta 300 Turismo con mascotas € por no diluir las micciones con agua jabonosa en el paseo marítimo peatonal. El transporte público local restringe el acceso de mascotas que superen los 10 kg de peso.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29901','mascotas','Parque Canino de la Batería y Alojamientos de la Cadena Meliá Hotels','Destino pionero en la hospitalidad y el ocio integrado. Destaca el gran recinto acotado para perros dentro del Parque de la Batería, equipado con césped natural, zonas arboladas de sombra y circuito de saltos ágiles. La zona centro y la barriada de La Carihuela concentran una altísima Turismo con mascotas densidad de restaurantes, heladerías y cafeterías que permiten comer con la mascota en el interior del local, lo que equilibra de forma sólida la falta de una playa canina urbana propia. Normativa: La normativa local prohíbe el baño de perros en todas sus playas urbanas durante la temporada oficial (junio a septiembre). Sin embargo, las ordenanzas comerciales son hiperpermisivas con el acceso a locales de ocio y restauración. Los hoteles urbanos aplican el programa "Pet Friendly" permitiendo perros de hasta 15-20 kg con entrega de kit de bienvenida en la habitación.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29094','mascotas','Playa Canina de Torre del Mar y Parque Canino del Tomillar','Referente absoluto del litoral de la Axarquía y uno de los destinos mejor equipados de la península. Su playa canina de Torre del Mar cuenta con arena fina, limpieza mecánica diaria, vallas de seguridad, una gran zona de juegos con aparatos de Agility (túneles, pasarelas), fuentes de doble nivel y un área exclusiva de duchas caninas de agua dulce. El sector de apartamentos y campings locales no impone límites de peso en el 40% de su oferta, complementado por un paseo marítimo repleto de chiringuitos adaptados. Con este bloque finaliza la auditoría técnica y de infraestructuras de la provincia de Málaga. Turismo con mascotas ¿Procedemos a avanzar de forma masiva con el primer bloque de la última provincia andaluza, Sevilla, siguiendo el orden alfabético de la comunidad? Elige una opción si deseas continuar: • Continuar con la provincia de Sevilla (Capital, Parques y Destinos de Interior). Normativa: Ordenanza de Playas vanguardista que regula de forma permanente una zona canina premium de más de 4.000 m² abierta los 365 días del año. Los animales pueden estar sueltos en el sector vallado. Obligatoriedad de censado genético para residentes, control sanitario riguroso para visitantes y multas de hasta 500 € por negligencias higiénicas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40002','mascotas','Parque Natural de Oromana y Zonas de Esparcimiento Canino Periféricas','Destino verde de la corona metropolitana muy valorado por el turismo activo de proximidad. El Parque de Oromana ofrece kilómetros de senderos arbolados junto al río Guadaíra ideales para el paseo canino. Cuenta con áreas valladas específicas dotadas de fuentes adaptadas. La hostelería local se concentra en terrazas amplias en las plazas del centro histórico con buena tolerancia general. Normativa: La Ordenanza de Convivencia Ciudadana permite el tránsito de perros con correa en todo el Monumento Natural. Prohibido soltar a los animales fuera de las áreas acotadas bajo multas de hasta 300 €. Los hoteles de la zona periférica enfocados al turismo de eventos aceptan mascotas bajo un límite general de 15 kg. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','mascotas','Red de Hoteles Monumentales, Parador de Carmona y Rutas de la Vega','Destino monumental de gran relevancia cultural. Destaca por una planta hotelera histórica de alta gama que facilita la pernoctación con perros pequeños y medianos, proporcionando kits de bienvenida. El urbanismo amurallado favorece el tránsito peatonal. Los restaurantes tradicionales con patios interiores andaluces registran un índice de aceptación intermedio, permitiendo comer con la mascota en zonas reservadas. Normativa: Normativa local estricta en el casco antiguo histórico: prohibido el acceso de perros sueltos y el uso de fuentes monumentales por animales, con sanciones de hasta 200 €. Tránsito obligatorio con correa. Los alojamientos de tipo casa palacio y el Parador nacional permiten mascotas en habitaciones seleccionadas aplicando suplementos de limpieza de unos 15-20 €/noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41038','mascotas','Gran Parque de la Dehesa de Doña María y Alojamientos de Conectividad Metropolitana','Núcleo residencial e industrial con una infraestructura verde en expansión. Su principal recurso es el Parque de la Dehesa de Doña María, que cuenta con una de las zonas de esparcimiento canino valladas más grandes del área metropolitana, equipada con circuitos de Agility completos y zonas de arbolado. Los hoteles de las principales avenidas de acceso ofrecen tarifas competitivas para familias que viajan con mascotas, sirviendo de base logística para visitar la capital. Normativa: Ordenanza de Tenencia de Animales obliga al registro genético de ADN canino. Los autobuses urbanos restringen el acceso a perros pequeños dentro de su transportín homologado. Áreas infantiles vetadas por completo para mascotas bajo riesgo de sanción de 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','mascotas','Red de Parques Urbanos (Parque de María Luisa, Alamillo), Red de Metro de Sevilla y Red TUSSAM','Gran capital monumental e internacional con una excelente infraestructura para mascotas. El Parque del Alamillo destaca de forma sobresaliente con un área canina de más de 3.000 m² dotada de una zona de baño fluvial controlada y juegos ágiles. La planta de hoteles de cadenas internacionales y hoteles boutique de los barrios de Santa Cruz y Triana lidera las políticas sin límite de peso. Prácticamente el 40% de los locales comerciales del centro y los restaurantes con terrazas junto al Guadalquivir muestran una tolerancia consolidada. Con este bloque finaliza la auditoría de la comunidad autónoma de Andalucía. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Aragón (comenzando por la provincia de Huesca). ¿Procedemos a iniciar el bloque de municipios pet-friendly de Aragón? Elige una opción si deseas continuar: • Iniciar la comunidad de Aragón (Provincia de Huesca, Pirineos y Turismo Activo). Normativa: La normativa del Metro de Sevilla permite el acceso de perros de todos los tamaños fuera de las horas punta, obligatoriamente con bozal y correa extensible a un máximo de 30 cm. La red de autobuses TUSSAM limita el acceso a mascotas en transportín, salvo la línea especial al aeropuerto que cuenta con pruebas piloto. Obligatorio diluir las micciones con agua jabonosa en el casco histórico bajo multas de hasta 120 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','mascotas','Senderos del Parque Natural Posets-Maladeta y Alojamientos de Alta Montaña','Gran polo de atracción internacional para el montañismo y el senderismo alpino en familia con perro. Sirve como base logística idónea para acometer rutas masivas como el Sendero Botánico o el acceso al Forau de Aigualluts. El sector privado destaca por ofrecer servicios premium que incluyen camas caninas de alta densidad, zonas de lavado para perros tras las caminatas en los hoteles y un volumen masivo de restaurantes de cocina aragonesa tradicional Turismo con mascotas que permiten el acceso de mascotas educadas a los comedores interiores. Normativa: La normativa del Parque Natural Posets-Maladeta exige llevar a los perros bajo control estricto (atados en zonas de pastoreo o presencia de ganado extensivo) para salvaguardar la fauna local y la ganadería productiva. El uso de correa es obligatorio en el interior del casco urbano histórico. Prácticamente el 60% de la planta hotelera y de apartamentos de montaña elimina por completo los límites de peso de las mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','mascotas','Parque del Encuentro (Zonas de Esparcimiento) y Red de Senderos Periurbanos','Núcleo urbano de interior que actúa como distribuidor turístico hacia el Pirineo. Su principal infraestructura es el Parque del Encuentro, equipado con un pipicán espacioso dotado de compuertas de seguridad automáticas y fuentes adaptadas para mascotas. Los hoteles urbanos céntricos muestran una política intermedia aceptando mascotas bajo solicitud con un límite genérico de 15 kg, mientras que la restauración del centro histórico concentra su apertura en amplias terrazas peatonales exteriores. Normativa: La Ordenanza de Seguridad y Convivencia prohíbe el acceso de mascotas sueltas en zonas verdes no acotadas, estableciendo sanciones por defecación sin recogida de hasta 300 €. Los autobuses urbanos restringen el transporte a perros pequeños alojados de forma permanente en transportines rígidos. Obligatorio el control de documentación sanitaria al día.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','mascotas','Red de Senderos del Monte San Cristóbal y Hoteles de la Cadena Oroel Turismo con mascotas','Capital histórica de los Pirineos con una altísima densidad de servicios orientados a familias con mascotas. El entorno del Monte San Cristóbal y el paseo de la cantera ofrecen kilómetros de rutas accesibles a pie de calle. La hostelería local de la zona monumental (alrededores de la Catedral y la Ciudadela) muestra una de las mayores tasas de aceptación en el interior de locales de toda la provincia, proporcionando recipientes de agua de cortesía y espacios amplios adaptados para perros. Normativa: Ordenanza municipal avanzada de tenencia que autoriza el paseo de perros sueltos con control visual en horarios nocturnos regulados (invierno de 20:00 a 09:00, verano de 22:00 a 09:00) en zonas verdes periféricas seleccionadas. Queda prohibido el acceso a monumentos históricos religiosos. Los hoteles y apartamentos turísticos aplican programas "Pet Welcome" que facilitan la estancia de perros medianos y grandes de hasta 25 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','mascotas','Entorno de Lanuza, Embalse de Lanuza y Estación de Esquí Aramón Formigal-Panticosa','Destino alpino de primer orden con un excelente recurso continental en el Embalse de Lanuza, donde múltiples zonas de orilla natural permiten el baño controlado y recreativo de las mascotas durante los meses de verano. El sector hotelero del núcleo de Formigal e infraestructuras tipo apartahotel destacan por una flexibilidad total sin discriminación de peso o raza, operando en sintonía con una red de asadores pirenaicos e instalaciones de restauración de alta montaña preparadas para recibir clientes acompañados de sus perros. Con este bloque cubrimos los puntos neurálgicos de mayor densidad de la provincia de Huesca. ¿Procedemos a avanzar de forma masiva con el siguiente bloque de Aragón correspondiente a la provincia de Teruel? Elige una opción si deseas continuar: • Continuar con la provincia de Teruel (Albarracín, Matarraña y Turismo Rural). Normativa: Normativas ambientales del Valle de Tena prohíben taxativamente la suelta de animales en las praderas de alta montaña durante el periodo estival para proteger los nidos de aves y rebaños. Los remontes y telecabinas de la estación invernal restringen el acceso a perros en temporada de esquí, pero flexibilizan el uso en verano en líneas de senderismo seleccionadas. Alojamientos exigen el pago de tarifas de limpieza fijas de entre 15 € y 25 € por estancia.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','mascotas','Red de Senderos del Paisaje Protegido de los Pinares de Rodeno y Alojamientos con encanto','Destino monumental de renombre internacional. Albarracín destaca por una red de alojamientos rurales independientes y pequeños hoteles boutique que eliminan el límite de peso en más del 40% de su planta alojativa. Las rutas senderistas periurbanas, como el Paseo Fluvial del Guadalaviar, son muy concurridas por familias con perros. Las tabernas y restaurantes con terrazas en la Plaza Mayor y mesones con patios tradicionales muestran una excelente predisposición, facilitando agua limpia. Normativa: La normativa del Paisaje Protegido de los Pinares de Rodeno exige llevar a los perros con correa obligatoria para proteger la fauna y las pinturas rupestres. En el casco histórico amurallado, de configuración estrecha y empedrada, el tránsito debe realizarse siempre bajo control. Los monumentos e interiores de museos locales restringen el acceso a mascotas, salvo perros de asistencia.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','mascotas','Parque de los Fueros-Ricardo Eced y Alojamientos Urbanos','Centro neurálgico y monumental de la provincia. Su mayor infraestructura pet-friendly es el Parque de los Fueros-Ricardo Eced, el pulmón verde de la ciudad, el cual cuenta con una zona de esparcimiento canino acotada con doble puerta y elementos básicos de juego. Los hoteles de la zona centro admiten mascotas bajo un límite estándar de 15 kg y con suplementos que oscilan entre los 10 € y 15 € por noche. Las terrazas de la Plaza del Torico concentran la actividad gastronómica accesible con perros. Normativa: La Ordenanza Municipal de Convivencia Ciudadana prohíbe el acceso de perros sueltos en zonas verdes no delimitadas, aplicando multas de hasta 300 € por deyecciones no retiradas. El transporte en autobuses urbanos limita el acceso a perros pequeños dentro de su correspondiente transportín homologado. Obligatorio el uso de correa corta en el centro histórico mudéjar.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44246','mascotas','Red de Alojamientos del Matarraña, Rutas del Río Matarraña y Entorno Natural','Capital de la comarca del Matarraña, conocida como la "Toscana aragonesa". Es un gran polo de turismo de naturaleza y escapadas rurales con mascotas, gracias a una oferta hotelera privada hiperpermisiva (casas rurales, hoteles de diseño integrado y campings) que no discrimina por tamaño, peso ni raza, ofreciendo amplias zonas de paseo. La restauración local destaca por su alta hospitalidad, permitiendo el acceso de perros educados a zonas de comedor interior y patios privados de un gran número de establecimientos. Con este bloque finaliza la auditoría de los núcleos con mayor peso turístico de la provincia de Teruel. ¿Procedemos a iniciar de forma masiva el bloque de la provincia de Zaragoza para completar la comunidad de Aragón? Elige una opción si deseas continuar: • Continuar con la provincia de Zaragoza (Capital, Parques Fluviales y Monasterio de Piedra). Normativa: Normativa comarcal orientada al agroturismo y la sostenibilidad. En el casco urbano histórico y monumental el uso de correa es obligatorio. Las pozas naturales de los ríos de la comarca (como las del río Tastavins o el propio Matarraña) tienen normativas específicas estacionales: se permite el baño de mascotas de manera controlada fuera de las zonas estrictamente balizadas para bañistas humanos en verano.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','mascotas','Red de Senderos Periurbanos y Alojamientos de la Comarca de Calatayud','Importante nodo monumental e histórico del Sistema Ibérico. Actúa como base logística de pernoctación hacia el turismo de naturaleza de la zona. Dispone de una planta alojativa compuesta por hoteles tradicionales y apartamentos vacacionales con una tolerancia intermedia. La restauración local concentra su oferta pet-friendly en amplias terrazas exteriores peatonales y mesones antiguos que cuentan con patios traseros adaptados. [1, 2]. Normativa: La Ordenanza Municipal de Convivencia exige el uso de correa obligatoria de un máximo de 1,5 metros en todo el entorno urbano y zonas ajardinadas históricas. Queda estrictamente prohibido el acceso de perros sueltos o el uso de fuentes públicas por animales. Los hoteles de la zona aplican límites de peso generalizados que promedian los 12-15 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','mascotas','Parque del Jardín Histórico del Monasterio de Piedra y Entorno del Embalse de la Tranquera','Enclave de primer orden y uno de los destinos turísticos naturales más visitados de Aragón. La posibilidad de recorrer el espectacular parque de cascadas, senderos y grutas junto a la mascota supone un fuerte reclamo de turismo familiar con perros de todos los tamaños. Los alojamientos rurales del propio municipio de Nuévalos y los campings periféricos destacan por no aplicar límites de peso rigurosos, ofreciendo instalaciones muy integradoras. [1, 2, 3, 4, 5, 6]. Normativa: La normativa de gestión privada del complejo monumental autoriza el acceso a perros educados al Parque del Jardín Histórico, siempre que permanezcan estrictamente atados. Prohibida la entrada de animales al interior de los edificios del Monasterio (iglesia, claustro, sala capitular). El entorno del Embalse de la Tranquera permite el tránsito y baño libre en zonas de orilla salvaje no balizadas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','mascotas','Parque del Agua Luis Buñuel, Red del Tranvía de Zaragoza y Red de Autobuses Avanza','Gran capital metropolitana con un extraordinario desarrollo de infraestructuras verdes. Sobresale el Parque del Agua Luis Buñuel, un gigantesco pulmón verde de 120 hectáreas provisto de amplias zonas de esparcimiento canino valladas, circuitos ágiles y senderos fluviales a orillas del Ebro. La hostelería del centro urbano y del casco histórico muestra un alto nivel de integración bajo el sello municipal pet-friendly, con más del 30% de los hoteles aceptando mascotas grandes y múltiples locales comerciales permitiendo el libre acceso interior. [1, 2, 3, 4, 5] Con este bloque finaliza la auditoría de la comunidad autónoma de Aragón. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Asturias. ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly del Principado de Asturias? Elige una opción si deseas continuar: • Iniciar la comunidad de Asturias (Gijón, Playas del Cantábrico y Picos de Europa). Normativa: La normativa de transporte local del Tranvía de Zaragoza permite el acceso de perros de más de 10 kg exclusivamente en el último vagón, con correa y bozal obligatorio; los perros de menos de 10 kg pueden ir en brazos. Los autobuses urbanos restringen el uso a mascotas de hasta 10 kg metidas en transportín rígido o bolso homologado. El consistorio prohíbe la suelta libre de perros en zonas verdes generales urbanas fuera de los espacios acotados específicos. El acceso con perro atado está permitido a dependencias administrativas municipales para realizar trámites.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','mascotas','Plan de Acceso a los Lagos de Covadonga y Alojamientos de los Picos de Europa','Epicentro del turismo rural y de montaña en el norte de España. Cangas de Onís destaca por una planta masiva de casas rurales y hoteles tradicionales donde más del 50% elimina por completo los límites de peso de las mascotas. El famoso puente Turismo con mascotas romano y los senderos fluviales del río Sella registran un impacto masivo de turismo familiar con mascotas. La hostelería local cuenta con una alta densidad de sidrerías con terrazas aclimatadas y hórreos habilitados donde se facilita el acceso con perros. Normativa: La normativa de uso regulado del Parque Nacional de los Picos de Europa prohíbe que los perros vayan sueltos por los senderos para evitar conflictos con el oso pardo, el lobo y el ganado vacuno extensivo. En el plan especial de transporte estival a los Lagos de Covadonga, se permite el acceso de perros de todos los tamaños en el maletero del autobús (en transportín del usuario) o en el interior del vehículo si son pequeños.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90012','mascotas','Playa Canina de Bayas (El Sablón)','Destino costero de gran valor ecológico. Su playa canina (El Sablón) es considerada una de las mejores y más extensas de todo el litoral cantábrico gracias a su fina arena dorada y su entorno salvaje rodeado de dunas protected. El arenal cuenta con servicios públicos de mantenimiento, duchas y fuentes caninas adaptadas. El sector de apartamentos vacacionales y surf camps locales está muy habituado al turismo con mascotas grandes, ofreciendo facilidades de lavado. Normativa: La Ordenanza de Playas regula un extenso tramo de casi 3 kilómetros de longitud en la zona oeste de la Playa de Bayas de manera permanente todo el año. Se autoriza la permanencia de perros sueltos tanto en la arena como en el agua dentro de la zona señalizada. Obligatorio mantener el control visual del animal. Los autobuses interurbanos exigen transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','mascotas','Rutas por los Acantilados del Cabo Vidio y Alojamientos Marineros Turismo con mascotas','Destino de gran atractivo visual e impacto turístico internacional. Cudillero suple la restricción de baño estival en sus playas con una excelente oferta de turismo activo por la red de senderos del Cabo Vidio y miradores costeros ideales para el paseo canino. Los hoteles rurales de los alrededores y las casas tradicionales asturianas muestran una tolerancia muy consolidada sin límites estrictos de peso, permitiendo a las familias utilizar el municipio como base residencial. Normativa: Prohibición estricta de acceso de perros a la arena de las playas urbanas e intermedias durante la temporada de baño alta (de junio a septiembre). El tránsito por el pintoresco anfiteatro marinero y las terrazas del puerto exige el uso de correa corta obligatoria. Sanciones de hasta 250 € por deyecciones no higienizadas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','mascotas','Playa Canina de El Rinconín, Parque del Cabo San Lorenzo y Sello "Gijón Dog Friendly"','Considerada de forma unánime una de las tres mejores ciudades de España para viajar con mascotas. El Ayuntamiento impulsa el sello oficial Gijón Dog Friendly, que aglutina a más del 40% de los comercios, bares, sidrerías y alojamientos locales con acceso interior permitido. La Playa de El Rinconín funciona de forma permanente todo el año como arenal canino, dotada de suelo de arena y roca, limpieza diaria, fuentes adaptadas y mangueras. Cuenta con parques masivos como el del Cabo San Lorenzo o Isabel la Católica con kilómetros de esparcimiento seguro. Normativa: Ordenanza municipal hipervanguardista. Permite el acceso de perros sueltos en más de 30 zonas verdes urbanas y parques Turismo con mascotas públicos en horarios específicos regulados. La icónica Playa de San Lorenzo permite el libre acceso de perros a la arena fuera de la temporada de salvamento (del 1 de octubre al 30 de abril). Obligatorio el uso de botellas de agua para limpiar micciones. Los autobuses urbanos de EMTUSA permiten perros de hasta 10 kg en transportines tipo bolso homologado.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','mascotas','Paseo de San Pedro y Alojamientos Rurales de la Costa Verde','Villa monumental y marinera de fuerte afluencia estival. Destaca por el Paseo de San Pedro, una alfombra de césped natural sobre los acantilados que ofrece vistas panorámicas espectaculares ideales para pasear con perros atados. Su mayor fortaleza reside en la periferia, donde la densidad de campings, bungalows y casonas asturianas de alquiler íntegro muestra una flexibilidad total sin discriminación por tamaño, absorbiendo el fuerte impacto de turismo familiar. Normativa: Normativa de costas muy estricta: prohibida la estancia de perros en la treintena de playas del concejo en verano. Tránsito obligatorio con correa en todo el casco histórico y sendas litorales protegidas. Los hoteles del núcleo urbano aplican límites de peso generalizados de entre 10 kg y 12 kg, exigiendo suplementos por noche. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90018','mascotas','Playa Canina de Cala Gamba / Cala des Gats y Complejo Zafiro Palace Palmanova','Destino vacacional de gran relevancia internacional. Ofrece una planta hotelera premium que ha integrado programas avanzados con habitaciones adaptadas en planta baja, obsequios de bienvenida y zonas valladas para el recreo. Las calas habilitadas son de dimensiones reducidas y suelo mixto de roca y arena, ideales para el refresco estival, complementadas por una gran densidad de terrazas gastronómicas integradoras en Palmanova y Santa Ponça. Normativa: La Ordenanza de Playas regula de forma exclusiva el acceso canino en la pequeña cala rocosa des Gats y en un tramo de Punta Marroig. Los animales deben estar censados y llevar correa en los accesos. Sanciones graves de hasta 600 € por presencia de animales en playas urbanas turísticas en temporada alta.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','mascotas','Calas del Entorno del Camí de Cavalls y Alojamientos de Agroturismo','Destino enfocado al ecoturismo y la desconexión. Ciutadella destaca por sus fincas de agroturismo y "llocs" tradicionales menorquines reconvertidos en hoteles de campo que aceptan mascotas medianas y grandes sin impedimentos rígidos de peso. El casco histórico peatonal es idóneo para pasear atados, y las terrazas del puerto natural muestran un índice de aceptación intermedio, facilitando cuencos de agua limpia. Normativa: Regulaciones de la reserva de la biosfera prohíben que los perros transiten sueltos por el Camí de Cavalls para evitar la erosión y molestias a la fauna. Prohibida la entrada de animales a las calas vírgenes del sur en temporada de baño. Los hoteles rurales exigen un comportamiento silencioso y aplican suplementos de limpieza de unos 15 €/noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07040','mascotas','Playa Canina de Es Carnatge, Parque de la Femu (Pipicán Grande) y EMT Palma','Gran capital insular y nodo logístico clave. Es Carnatge es una zona costera natural protegida de roca y arena fina donde los perros pueden correr sueltos y bañarse en un entorno abierto de gran longitud. El tejido urbano cuenta con parques dotados de amplias áreas de agilidad valladas con dobles puertas. El sector hotelero urbano boutique del centro histórico acepta mascotas de forma generalizada, operando en consonancia con cafeterías de especialidad y tiendas de moda que permiten el acceso interior. Normativa: La Ordenanza Municipal de la EMT Palma permite el acceso de perros a las líneas de autobuses urbanos principales con bozal, correa corta y previo pago de billete específico. Obligatoriedad estricta de portar botella de agua para limpiar micciones. La Playa de Es Carnatge está declarada zona de libre acceso canino todo el año de forma permanente. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90851','mascotas','Tramos de Playa Canina en la Desembocadura del Río y es Faralló','El municipio de perfil más familiar y receptivo con mascotas de toda la isla de Ibiza. El tramo situado en la zona sur de la desembocadura del río ofrece un espacio de arena fina y aguas someras ideal para perros de todos los tamaños. La oferta hostelera destaca por agroturismos de alto nivel y hoteles boutique que facilitan camas y comederos especiales. El paseo marítimo cuenta con una excelente concentración Turismo con mascotas de restaurantes con terrazas sombreadas adaptadas para el descanso familiar. Con este bloque finaliza la auditoría de los puntos clave de las Islas Baleares. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Canarias (comenzando por la provincia de Las Palmas). ¿Procedemos a iniciar el bloque de municipios pet-friendly de Canarias? Elige una opción si deseas continuar: • Iniciar la comunidad de Canarias (Provincia de Las Palmas, Gran Canaria, Lanzarote y Playas Caninas). Normativa: El Ayuntamiento regula dos pequeños tramos litorales permanentes habilitados para el baño de perros todo el año. Uso obligatorio de correa fuera de las zonas acotadas de arena. Sanciones de hasta 300 € por no recogida de excrementos. Alojamientos y agroturismos de la zona aplican políticas de admisión muy flexibles pero exigen reservas con antelación.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90628','mascotas','Playa de la Arena, Parque Canino de Altavista y Alojamientos Urbanos','Capital de la isla de Lanzarote que sirve de base para el turismo urbano y comercial. Cuenta con el Parque Canino de Altavista, un recinto cerrado de más de 800 m² dotado de circuito de agilidad básico. La planta hotelera local es intermedia, admitiendo mascotas bajo un límite de peso que ronda los 12-15 kg. La oferta de restauración en el Charco de San Ginés ofrece terrazas peatonales con un buen nivel de acogida y disponibilidad de agua limpia para los perros. Normativa: Ordenanza Reguladora de la Tenencia de Animales prohíbe el acceso de perros a las playas más céntricas e icónicas (como El Reducto) bajo multas de hasta 300 €. Se habilita de forma permanente un tramo en la periferia de la ciudad. Uso obligatorio de correa en vías públicas y zonas comerciales peatonales. El transporte interurbano exige transportín rígido en bodega.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','mascotas','Playa Canina de Bocabarranco, Parque de El Sebadal y Red de Parques Urbanos','Gran capital metropolitana con un excelente tejido de parques urbanos para el esparcimiento animal. Destacan los recintos vallados del Parque Juan Pablo II y el Parque de El Sebadal, con miles de metros cuadrados de superficie, zonas arboladas y equipamiento ágil profesional. La planta de hoteles boutique urbanos del barrio histórico de Vegueta y de la zona portuaria muestra una alta tolerancia, ofreciendo estancias adaptadas sin límites de peso estrictos en categorías seleccionadas. Normativa: El Ayuntamiento regula de forma permanente la Playa de Bocabarranco (Jinámar) como arenal apto para el baño de mascotas todo el año. Prohibido terminantemente el acceso a la arena de Las Canteras, lo que acarrea sanciones graves. La normativa de transporte en Guaguas Municipales restringe el acceso general de perros medianos/grandes, permitiendo solo animales Turismo con mascotas pequeños en transportín. Obligatorio el censo por ADN canino.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','mascotas','Entorno Residencial de Maspalomas y Complejo Seaside Palm Beach','Principal motor turístico del sur de la isla que suple las restricciones de sus playas con una planta hotelera privada internacional de primer nivel. Cuenta con resorts de lujo y complejos de bungalows que ofrecen programas avanzados para mascotas, incluyendo camas específicas, servicios de Turismo con mascotas paseadores locales y áreas de picnic exteriores adaptadas. La densidad de restauración con amplias terrazas protegidas del viento y el sol ofrece una excelente hospitalidad a las familias con perro. Normativa: Ordenanzas ambientales y de costas hiperrestrictivas en la Reserva Natural Especial de las Dunas de Maspalomas: prohibido terminantemente el acceso con perros sueltos o atados en todo el entorno dunar y sus playas protegidas bajo sanciones severas. Los centros comerciales abiertos y paseos marítimos de Meloneras permiten el tránsito con correa corta.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','mascotas','Playa de las Coloradas (Playa Afre) y Alojamientos Turísticos de Playa Blanca','Destino vacacional destacado en el sur de Lanzarote. Su playa canina cuenta con un suelo mixto de arena fina y picón (arena negra volcánica), equipada con papeleras específicas, aunque carece de duchas. El paseo marítimo de Playa Blanca y el puerto deportivo Marina Rubicón concentran una gran oferta de restauración y cafeterías que aceptan mascotas de forma habitual en sus terrazas. El sector de villas de alquiler vacacional destaca por su permisividad, facilitando estancias en parcelas valladas independientes. Con este bloque finaliza la auditoría de la provincia de Las Palmas. Siguiendo el orden jerárquico del archipiélago, la siguiente Turismo con mascotas provincia a auditar es Santa Cruz de Tenerife (Tenerife, La Palma, La Gomera, El Hierro). ¿Procedemos a iniciar el bloque de la provincia de Santa Cruz de Tenerife. Normativa: El Ayuntamiento de Yaiza autoriza el acceso y baño de perros de forma permanente en un tramo acotado de la Playa de las Coloradas. El horario regulado establece el uso de correa obligatorio excepto dentro del agua. Queda prohibido el acceso a las playas vírgenes de Papagayo por motivos de protección medioambiental.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38032','mascotas','Playa de El Tabaibal','Destino costero residencial cercano al área metropolitana. La playa canina de El Tabaibal cuenta con una superficie de charcos y suelo de roca volcánica acondicionada con pasarelas de acceso, siendo un punto de encuentro habitual para el refresco estival de mascotas de todos los tamaños. La oferta hotelera y de restauración local es moderada, concentrando la aceptación de perros en las terrazas de los restaurantes tradicionales de pescado del litoral. Normativa: Ordenanza de Playas regula de forma exclusiva el acceso canino a este tramo costero. Uso obligatorio de correa fuera de la zona de baño balizada. Sanciones por deyecciones no higienizadas de hasta 300 €. El transporte interurbano en guaguas restringe el acceso a animales grandes, permitiendo solo perros pequeños en transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38017','mascotas','Playa de El Cabezo (El Médano) y Rutas de Windsurf / Senderismo canino','Epicentro del turismo deportivo y de viento en el sur de Tenerife. La playa canina ofrece un espacio amplio de arena dorada fina y Turismo con mascotas aguas someras ideal para el esparcimiento masivo de las mascotas. La planta alojativa del entorno de El Médano (apartamentos vacacionales y campings) muestra una flexibilidad muy elevada sin límites rígidos de peso. Cuenta con una gran concentración de terrazas de ambiente surfero y multicultural que facilitan agua limpia y un trato excelente a las familias con perro. Normativa: El Ayuntamiento autoriza de manera permanente un tramo de la Playa de El Cabezo exclusivamente para el uso recreativo de perros todo el año. Se exige mantener al animal controlado con correa hasta llegar al espacio acotado. Sanciones de hasta 450 € por acceso a las dunas o playas protegidas colindantes.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38020','mascotas','Playa de El Puertito (Playa canina permanente) y Senderos del Malpaís de Güímar','Gran referente del turismo costero pet-friendly en la isla. La playa cuenta con arena negra volcánica de excelente mantenimiento, limpieza higiénica diaria, papeleras específicas y fuentes adaptadas para mascotas. El entorno del paseo marítimo destaca por su alta densidad de locales de restauración y terrazas que permiten el acceso de perros educados, consolidando un ambiente familiar e integrador muy valorado por los visitantes de larga estancia. Normativa: Ordenanza municipal pionera en Tenerife al regular un tramo permanente de más de 200 metros en la Playa de El Puertito de Güímar. Permite la permanencia de perros sueltos tanto en la arena como en el agua dentro de la zona delimitada. Obligatorio portar la cartilla sanitaria al día.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38024','mascotas','Red de Alojamientos Rurales de la Caldera de Taburiente y Senderos de interior','Destino enfocado al ecoturismo y al turismo de aventura con mascotas. Los Llanos de Aridane destaca por una planta de casas de campo tradicionales y villas independientes que facilitan terrenos vallados ideales para perros grandes. El centro urbano peatonal cuenta con plazas arboladas aptas para el paseo, y las cafeterías y locales de restauración muestran un nivel de tolerancia intermedio, enfocando sus servicios pet-friendly en amplias zonas exteriores sombreadas. Con este bloque finaliza la auditoría de la comunidad autónoma de Canarias. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Cantabria. ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de Cantabria? Elige una opción si deseas continuar: • Iniciar la comunidad de Cantabria (Santander, San Vicente de la Barquera, Playas del Cantábrico y Marismas) Turismo con mascotas. Normativa: La normativa de uso del Parque Nacional obliga a que los perros transiten estrictamente atados para proteger las especies endémicas y la avifauna canaria. Queda prohibida la entrada de animales a las zonas de acampada centrales. Los alojamientos rurales de la comarca exigen suplementos variables que rondan los 10-15 € por noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39020','mascotas','Playa Canina de Arcisero, Muelle Oriñón y Playa de Cargadero','Destino fronterizo con el País Vasco de alta relevancia turística. Ofrece una planta de alojamientos vacacionales y apartamentos turísticos muy flexible para perros medianos y grandes. La playa de Arcisero destaca por su espectacular entorno natural de roca y oleaje moderado, ideal para mascotas Turismo con mascotas habituadas. El sector hostelero del puerto cuenta con una alta densidad de tabernas tradicionales que permiten mascotas en terrazas exteriores con equipamiento de sombra. Normativa: La Ordenanza Municipal de Playas habilita tres zonas permanentes (Arcisero, Cargadero y Mioño) para el uso con mascotas todo el año. Prohibido el acceso a los arenales principales (Ostende y Brazomar) en temporada alta (de junio a septiembre) bajo sanciones de hasta 300 €. Uso obligatorio de correa en accesos y paseos marítimos.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','mascotas','Tramo Canino de la Playa de Helgueras y Parque Natural de las Marismas de Santoña','Importante nodo de turismo familiar de verano. La playa canina autorizada cuenta con arena fina y un paisaje de rocas marinas muy valorado durante la bajamar, aunque el acceso peatonal requiere una caminata prolongada desde las zonas urbanas de estacionamiento. La infraestructura hotelera periférica y los campings locales aceptan perros medianos bajo suplemento, destacando las terrazas de los restaurantes del centro de la villa por su hospitalidad. Normativa: Ordenanza de Playas restringe el uso canino estival a la zona final de la Playa de Trengandín (sector Helgueras). Las normativas ambientales del Parque Natural prohíben la suelta libre de mascotas por las marismas y dunas para preservar el ecosistema de aves acuáticas. Sanciones por defecación sin recogida de hasta 450 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','mascotas','Playa de la Maza (Playa de los Vagos) y Red de Senderos del Parque Natural de Oyambre Turismo con mascotas','Uno de los grandes referentes del turismo costero pet-friendly del norte peninsular. La Playa de la Maza ofrece aguas tranquilas, arena fina dorada y una gran extensión ideal para cachorros y perros medianos, equipada con papeleras específicas. La planta de campings, bungalows y posadas rurales del entorno de Oyambre muestra una flexibilidad absoluta sin discriminación estricta de peso, operando con una red de asadores tradicionales que facilitan la estancia familiar. Normativa: Ordenanza pionera que regula de forma exclusiva y permanente la Playa de la Maza (ubicada en el interior de la ría) para el baño y esparcimiento de mascotas. En el resto del parque de Oyambre los perros deben transitar atados por caminos y pistas. Los taxis locales muestran un índice de aceptación intermedio bajo aviso previo.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','mascotas','Red de Parques Urbanos (Parque de la Vaguada de las Llamas), Líneas de Cercanías Cantabria de Renfe y Red TUS','Gran capital administrativa y cultural. Destaca por el Parque de la Vaguada de las Llamas, un pulmón verde de gran extensión provisto de zonas de esparcimiento canino valladas y circuitos básicos de agilidad. La planta de hoteles de cadenas urbanas acepta mascotas bajo un estándar medio de 15 kg. El centro comercial abierto de la ciudad y las terrazas del Paseo de Pereda muestran un alto índice de aceptación, complementado por la conectividad ferroviaria panorámica costera. [1, 2, 3]. Normativa: La Ordenanza del Servicio de Transportes Urbanos de Santander (TUS) autoriza el viaje de mascotas pequeñas de forma Turismo con mascotas obligatoria en transportín rígido. Las líneas de Cercanías Cantabria de Renfe son hiperpermisivas, admitiendo perros sin límite de peso, atados y con bozal, de manera gratuita. Queda prohibido el baño y permanencia de mascotas en las playas urbanas (El Sardinero, Los Peligros) en época estival alta.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39085','mascotas','Playa Canina de la Riberuca y Red de Paseos Fluviales','Destino veraniego de perfil deportivo. La playa para mascotas está situada en una zona de estuario con suelo de arena fina combinada con algo de lodo y algas según las corrientes de la ría, Turismo con mascotas contando con equipamiento básico de señalización. El sector de apartamentos vacacionales y hostales residenciales absorbe el impacto del turismo familiar, sirviéndose de paseos fluviales periféricos idóneos para caminatas seguras. Con este bloque finaliza la auditoría de los principales focos litorales y urbanos de la provincia de Cantabria. ¿Procedemos a iniciar de forma masiva el bloque de la comunidad autónoma de Castilla-La Mancha, continuando el orden alfabético estricto de nuestro proyecto nacional? Elige una opción si deseas continuar: • Iniciar la comunidad de Castilla-La Mancha (Toledo, Cuenca, Lagunas de Ruidera y Turismo de Interior). Normativa: Habilitado de forma permanente el tramo de la Playa de la Riberuca para el acceso con mascotas. Prohibido terminantemente transitar con perros sueltos por los arenales de Los Locos o La Concha durante el periodo estival, acarreando multas de hasta 300 €. Los hoteles aplican límites generales fijados en los 12 kg por animal.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','mascotas','Senderos de las Hoces del Júcar y del Huécar, y Parque de los Príncipes','Ciudad Patrimonio de la Humanidad con un entorno geográfico excepcional para el senderismo periurbano. Las rutas que bordean las Hoces permiten largos paseos con mascotas en un paisaje natural único. El Parque de los Príncipes ofrece un área de esparcimiento canino vallada con elementos básicos de agilidad. La planta hotelera local (hoteles tradicionales y apartamentos rurales) acepta mascotas de forma intermedia con un límite general de 15 kg. Normativa: La Ordenanza Municipal de Medio Ambiente obliga al uso de correa en todo el casco histórico y zonas verdes urbanas. El acceso a monumentos principales y museos está restringido. Los autobuses urbanos limitan el tránsito a perros pequeños en transportín rígido. Sanciones por no recogida de deyecciones de hasta 300 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02019','mascotas','Playas Continentales del Parque Natural de las Lagunas de Ruidera','Gran polo de atracción estival para el turismo de interior con mascotas. Las lagunas que corresponden a este término municipal ofrecen excelentes playas continentales de aguas cristalinas ideales para el refresco canino. El sector privado de la zona (casas rurales independientes, campings y bungalows) destaca por su alta permisividad, eliminando el límite de peso en el 50% de sus instalaciones y facilitando parcelas valladas. Normativa: La normativa del Plan Rector de Uso y Gestión (PRUG) del Parque Natural permite el acceso de perros atados a los senderos. Se autoriza el baño de mascotas exclusivamente en las zonas de orilla salvaje no balizadas para bañistas humanos durante la temporada estival. Queda prohibida la suelta libre de animales en zonas de nidificación de aves acuáticas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','mascotas','Red de Alojamientos Rurales de la Comarca y Parque de la Alameda','Destino monumental e histórico muy demandado por el turismo familiar de proximidad de la zona centro de España. Su principal fortaleza reside en los alojamientos rurales periféricos, que muestran una flexibilidad total sin discriminación de tamaño. El Parque de la Alameda ofrece un entorno arbolado amplio para el paseo, y las tabernas tradicionales de la Plaza Mayor cuentan con terrazas muy habituadas a dar servicio a clientes con perro. Normativa: Normas municipales estrictas enfocadas a la preservación del patrimonio medieval. Uso de correa obligatorio en todo el conjunto histórico. El Parador nacional y los hoteles boutique locales aceptan mascotas medianas bajo reserva previa y aplicando suplementos de limpieza de unos 15 €/noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','mascotas','Senda Ecológica del Tajo, Parque de las Tres Culturas y Red de Hoteles Urbanos','Gran capital cultural e histórica con un urbanismo peatonal muy exigente pero disfrutable. Destaca de forma sobresaliente la Senda Turismo con mascotas Ecológica del Tajo, un recorrido perimetral de varios kilómetros junto al río ideal para caminar de forma segura con mascotas. El Parque de las Tres Culturas dispone de un pipicán de grandes dimensiones vallado. La planta de hoteles de cadenas internacionales del entorno metropolitano lidera las políticas sin límite de peso, ofreciendo una base logística excelente. Con este bloque finaliza la auditoría de los focos de mayor relevancia e infraestructura consolidada de Castilla-La Mancha. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Castilla y León. ¿Procedemos a iniciar el bloque de municipios pet-friendly de Castilla y León? Elige una opción si deseas continuar: • Iniciar la comunidad de Castilla y León (Burgos, Salamanca, Valladolid, León y Playas Fluviales). Normativa: La Ordenanza Municipal de Tenencia de Animales prohíbe la presencia de perros sueltos en el casco histórico, acarreando multas de hasta 150 €. Obligatorio el uso de botellas de agua para limpiar micciones. El transporte urbano colectivo restringe el acceso a perros de asistencia y mascotas en transportín homologado.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','mascotas','Paseo de la Isla, Parque de Fuentes Blancas y Red de Autobuses SMYT','Ciudad monumental clave en el Camino de Santiago con un extraordinario cinturón verde. El Parque de Fuentes Blancas y el histórico Paseo de la Isla ofrecen kilómetros de senderos arbolados a orillas del río Arlanzón, equipados con zonas de esparcimiento canino valladas de gran extensión. La planta hotelera del centro histórico acepta mascotas bajo un límite de peso medio (generalmente 15 kg), mientras que los mesones tradicionales de la zona de la Catedral muestran una alta receptividad en sus terrazas. Normativa: La Ordenanza Municipal de Limpieza exige el uso obligatorio de correa en todo el entorno urbano histórico, aplicando multas de hasta 300 € por deyecciones no retiradas. El servicio de autobuses urbanos SMYT limita el acceso de mascotas a perros de asistencia y pequeños animales domésticos en transportín rígido y cerrado.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90082','mascotas','Playa Fluvial del Embalse de El Burguillo','Gran polo de atracción estival para el turismo de interior de la zona centro de España. El embalse de El Burguillo ofrece playas continentales de aguas tranquilas rodeadas de pinares, ideales para el refresco canino. La infraestructura turística local destaca por una gran oferta de casas rurales independientes y campings que eliminan los límites de peso de las mascotas y facilitan amplias parcelas cerradas. Normativa: El Ayuntamiento regula el uso del embalse permitiendo el baño de perros de forma controlada exclusivamente en las zonas de orilla natural no balizadas para bañistas humanos. Obligatorio el uso de correa en los accesos y caminos perimetrales. Sanciones por abandono de residuos de hasta 200 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','mascotas','Parque Público del Río Bernesga y Red de Alojamientos del Barrio Húmedo','Destino cultural y gastronómico de alta demanda. Su mayor infraestructura verde es el parque lineal que acompaña al río Bernesga, provisto de amplias praderas y áreas valladas específicas para perros con elementos de juego ágil. El famoso Barrio Húmedo y el Barrio Romántico concentran una altísima densidad de tabernas y bares de tapas que permiten el acceso de perros educados a sus terrazas y zonas de barra interiores, facilitando el turismo de ocio familiar. Normativa: Normas municipales estrictas enfocadas a la protección del patrimonio gótico. Tránsito obligatorio con correa de longitud máxima de 1,5 metros en el casco viejo. Los hoteles de la zona centro admiten mascotas aplicando suplementos de limpieza de unos 12-15 € por noche. Los Turismo con mascotas autobuses locales restringen el acceso a transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','mascotas','Parque del Temple y Sello Turístico "Ponferrada Dog Friendly"','Capital de la comarca de El Bierzo y un gran referente nacional en turismo petfriendly. Cuenta con una red oficial de establecimientos, comercios y hoteles adheridos que permiten el acceso interior de mascotas sin discriminación de tamaño. El Parque del Temple ofrece más de 2.000 m² acotados de césped con circuitos de Agility. Sirve además como base logística excelente para recorrer parajes naturales como Turismo con mascotas Las Médulas, donde las rutas de senderismo son completamente accesibles con perro. Normativa: Ordenanza municipal pionera que permite el acceso de perros sueltos con control visual en varios parques de la ciudad en horarios nocturnos regulados. El Ayuntamiento impulsa campañas activas de integración comercial. Obligatorio portar botella de agua para limpiar micciones caninas bajo riesgo de sanción de 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','mascotas','Parque Fluvial del Tormes, Huerto de Calixto y Melibea y Red Renfe Media Distancia','Ciudad universitaria de relevancia internacional. Destaca el desarrollo del Parque Fluvial del Tormes, un gran entorno natural urbano acondicionado con amplias zonas de esparcimiento canino valladas, fuentes a doble altura y senderos peatonales seguros. Los hoteles boutique del centro urbano eliminan las restricciones de peso en habitaciones seleccionadas. El sector hostelero de la Plaza Mayor y calles peatonales ofrece terrazas muy habituadas a dar servicio a clientes con mascotas. Normativa: La Ordenanza de Convivencia autoriza el tránsito de perros con correa en las zonas monumentales de piedra villamayor. Las líneas de Renfe Media Distancia que conectan la ciudad permiten viajar con perros de hasta 10 kg en transportín, cobrando una tasa sobre el billete. Prohibido el acceso de animales sueltos en el centro histórico, con multas de hasta 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','mascotas','Playa Fluvial de las Moreras, Campo Grande y Red AUVASA Turismo con mascotas','Núcleo urbano moderno con excelentes servicios de hospitalidad. Su recurso más singular es la Playa de las Moreras, un arenal fluvial artificial a orillas del río Pisuerga que sirve de punto de recreo y refresco canino controlado. La ciudad ofrece múltiples parques con pipicanes vallados equipados con juegos de agilidad bien conservados. La planta de hoteles de cadenas internacionales del centro administrativo lidera las políticas sin límite de peso, proporcionando kits de bienvenida. Con este bloque finaliza la auditoría de los focos de mayor relevancia e infraestructura consolidada de Castilla y León. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Cataluña. ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de Cataluña (comenzando por la provincia de Barcelona)? Elige una opción si deseas continuar: • Iniciar la comunidad de Cataluña (Provincia de Barcelona, Playas Caninas, Parques y Cercanías). Normativa: La normativa de la red de autobuses urbanos AUVASA autoriza el acceso de perros de hasta 10 kg metidos en transportines tipo bolso homologado. Se permite el paseo de perros atados en el histórico parque de Campo Grande por los caminos autorizados. La Playa de las Moreras cuenta con una ordenanza de uso específico fuera de la temporada alta de baño humano.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90024','mascotas','Playa Canina de Badalona (tramo de la Playa de los Patines de Vela) y Parques de Can Solei y Ca l''Arnús','Destino costero metropolitano de alta demanda. La playa para mascotas cuenta con arena fina, limpieza de filtrado diario y vallado perimetral de seguridad para evitar fugas hacia el paseo marítimo. Los históricos Parques de Can Solei y Ca l''Arnús ofrecen amplias zonas de paseo arboladas con espacios de socialización canina cerrados. La hostelería local de primera línea cuenta con terrazas muy habituadas al turismo familiar con perros, ofreciendo recipientes de agua de cortesía de forma sistemática. Normativa: La Ordenanza Municipal de Playas regula un espacio de unos 250 metros lineales reservado exclusivamente para perros durante la temporada de baño estival alta (junio a septiembre). Obligatorio el uso de correa en los accesos de arena. Conectividad directa con la Red de Cercanías Renfe de Barcelona (Rodalies), que permite perros de todos los tamaños atados y con bozal fuera de las horas punta de lunes a viernes. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','mascotas','Área Canina de la Playa de Llevant, Red de Metro de Barcelona (TMB), Parque de la Ciutadella y Parque Güell','Gran capital icónica mundial del turismo urbano integrado. Dispone de una infraestructura pública masiva que incluye más de 100 Áreas de Recreo Canino (zonas compartidas en horarios Turismo con mascotas específicos) y Espacios de Perros en parques urbanos de gran tamaño, como el Parque del Clot o la Estación del Norte. La planta de hoteles boutique y hoteles de cadenas internacionales (como las marcas W Barcelona o Kimpton) lidera las políticas "Pet-Inclusion" avanzadas, eliminando límites de peso, permitiendo el acceso a zonas comunes seleccionadas y ofreciendo menús caninos. Más del 45% de los locales comerciales y restaurantes del centro histórico admiten el libre acceso de perros educados a su interior. Normativa: La normativa de Transports Metropolitans de Barcelona (TMB) permite el acceso de perros de todos los tamaños al Metro con bozal y correa no extensible (menor a 50 cm), restringido exclusivamente en horas punta de días laborables. La red de autobuses urbanos limita el acceso a perros en transportín. Obligatoriedad estricta de portar botella de agua para limpiar micciones y retirada inmediata de deyecciones bajo sanciones de hasta 600 €. El Ayuntamiento regula de forma permanente un tramo vallado de 1.200 m² en la Playa de Llevant durante el verano.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08056','mascotas','Playa Canina de Castelldefels y Parque de la Muntanyeta','Gran polo de turismo vacacional y de proximidad. Su playa canina está considerada una de las mejor equipadas de la provincia: cuenta con suelo de arena fina dorada, limpieza mecánica reforzada, duchas caninas específicas con mangueras de agua dulce, fuentes a doble nivel adaptadas y papeleras de reciclaje. El Parque de la Muntanyeta ofrece un espacio interior boscoso para Turismo con mascotas caminatas complementarias. El sector hotelero y de apartamentos de la zona costera cuenta con una altísima densidad de alojamientos y chiringuitos de diseño que permiten comer con la mascota de forma confortable. Normativa: Ordenanza de Playas vanguardista que habilita un espacio permanente de más de 60 metros de ancho y 500 metros lineales para el uso de mascotas. Está permitido el baño de animales y la permanencia sin correa exclusivamente dentro del recinto delimitado por vallas de madera. Sanciones de hasta 400 € por tránsito de perros sueltos fuera del área canina. Los taxis locales muestran una excelente tasa de aceptación bajo preaviso.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','mascotas','Playa Canina del Poblenou (Pineda de Mar) y Hoteles de la Costa del Maresme','Destino costero especializado en turismo familiar en la comarca del Maresme. La playa canina ofrece un arenal de gran extensión con arena gruesa y aguas limpias de profundidad moderada, equipada con pasarelas de acceso de madera y contenedores de residuos específicos. La planta de campings y bungalows de los alrededores destaca por su flexibilidad, eliminando el límite de peso en parcelas seleccionadas. La restauración local ofrece una excelente hospitalidad en áreas de terrazas exteriores cubiertas. Normativa: El Ayuntamiento autoriza de manera permanente un tramo de la Playa del Poblenou (límite con Calella) exclusivamente para el disfrute y baño de mascotas los 365 días del año. Los perros pueden permanecer sueltos en el recinto vallado. Obligatorio el uso de correa en el paseo marítimo peatonal. Los hoteles del núcleo urbano aplican un límite de peso medio fijado generalmente en los 15 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','mascotas','Playa Canina de Vallcarca, Parque Natural del Garraf y Alojamientos Boutique','Destino turístico cosmopolita de relevancia internacional. Su playa de Vallcarca ofrece un entorno tranquilo de suelo mixto de arena fina y guijarros con aguas cristalinas. Destaca por una planta de apartamentos turísticos de alquiler vacacional y hoteles boutique con políticas avanzados que aceptan mascotas grandes y ofrecen kits de bienvenida (snacks, juguetes y camas). El centro histórico peatonal y el paseo marítimo concentran una altísima densidad de restaurantes, terrazas y cafeterías de diseño donde comer con la mascota en el interior es una práctica completamente normalizada. Con este bloque finaliza la auditoría técnica de los principales focos litorales y metropolitanos de la provincia de Barcelona. ¿Procedemos a iniciar de forma masiva el bloque de la provincia de Girona (Costa Brava y Pirineo Catalán), continuando el orden Turismo con mascotas alfabético estricto de Cataluña? Elige una opción si deseas continuar: • Continuar con la provincia de Girona (Costa Brava, Playa de la Rubina y Pirineos). Normativa: La ordenanza municipal prohíbe el acceso de perros a la arena de las playas urbanas del centro (San Sebastián, La Ribera) en verano. Se deriva el uso canino a la Playa de Vallcarca en entorno industrial-natural de forma permanente. En el Parque Natural del Garraf el uso de correa es estrictamente obligatorio para proteger la fauna mediterránea. Los establecimientos comerciales operan bajo libre derecho de admisión con una tendencia hiperpermisiva.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90889','mascotas','Playa de la Rubina y Complejo Castell Mar Camping','El gran templo del turismo costero pet-friendly en España. La Rubina destaca por su arena fina dorada, dunas naturales y aguas poco profundas de oleaje moderado, equipada con duchas caninas y personal de concienciación. Los macrocampings de la localidad ofrecen servicios premium únicos en Europa: restaurantes con menús caninos, duchas para perros con secadores profesionales, zonas de agilidad valladas de más de 1.000 m² y piscinas exclusivas para mascotas, eliminando cualquier límite de peso o raza. Normativa: Ordenanza municipal pionera y referente europeo. Autoriza de forma permanente el acceso, permanencia y baño libre de perros sin correa en un tramo de más de 200 metros en la Playa de la Rubina (dentro del Parque Natural de las Marismas del Ampurdán) todo el año. Normas higiénicas estrictas con multas de hasta 400 € por abandono de residuos. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18005','mascotas','Parques de las Devesas de Salt y Girona, el Barri Vell y Red de Hoteles Urbanos','Ciudad monumental e histórica con un urbanismo peatonal muy disfrutable a orillas del Oñar. Su principal pulmón verde es el Parque de la Devesa, que cuenta con amplios senderos arbolados idóneos para caminar de forma segura con mascotas y dispone de un área de esparcimiento canino vallada con elementos básicos. Los hoteles boutique del centro urbano aceptan mascotas de tamaño pequeño y mediano (hasta 15 kg), operando en sintonía con una red de cafeterías y comercios del Barri Vell hiperpermisivos con el acceso interior. Normativa: La Ordenanza Municipal de Tenencia de Animales prohíbe el tránsito de perros sueltos en el núcleo histórico monumental, con multas de hasta 300 € por deyecciones no retiradas. Obligatorio el uso de botellas de agua para diluir las micciones. Los autobuses urbanos limitan el tránsito a perros pequeños dentro de su correspondiente transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90610','mascotas','Playa de Sant Jordi, Playa de la Farella (tramos regulados) y Caminos de Ronda Turismo con mascotas','Destino de la Costa Brava norte especializado en turismo activo de naturaleza. Las calas autorizadas ofrecen un suelo mixto de arena gruesa y guijarros con aguas hipercristalinas ideales para el buceo canino, contando con señalización clara y mantenimiento higiénico. Los senderos costeros de los Caminos de Ronda registran un alto volumen de excursiones familiares con perros, conectando con restaurantes que muestran una excelente predisposición en sus terrazas. Normativa: Ordenanza de Playas avanzada que reserva dos tramos litorales específicos de forma permanente para el baño de mascotas todo el año. Uso obligatorio de correa en los tramos de enlace de los Caminos de Ronda costeros. Sanciones por no retirada de excrementos de hasta 300 €. Los hoteles de la zona costera aplican un límite de peso medio fijado en los 15 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17145','mascotas','Cremallera de Núria, Vall de Núria y Alojamientos del Pirineo Oriental','Destino alpino de alta montaña excepcional. La conectividad de transporte público adaptada facilita de forma masiva que las familias accedan con sus perros a un valle pirenaico virgen a más de 2.000 metros de altitud para realizar rutas de senderismo de alta cota. La planta de alojamientos locales (hoteles de montaña, hostales y apartamentos rurales de la comarca del Ripollés) destaca por una flexibilidad total sin discriminación estricta de peso, cooperando de forma estrecha con asadores de montaña integradores. Con este bloque finaliza la auditoría de los focos clave de la provincia de Girona. ¿Procedemos a continuar de forma masiva con la provincia de Lleida (Pirineos, Valle de Arán y Parques Nacionales). Normativa: El tren Cremallera de Núria (operado por FGC) es un referente de movilidad: permite el acceso de perros de todos los Turismo con mascotas tamaños de forma gratuita en coches seleccionados, viajando atados y con bozal obligatorio. En el entorno de la estación de esquí alpina de montaña de Vall de Núria los perros deben transitar controlados con correa para evitar conflictos con la fauna e interrupciones en los pastos extensivos.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','mascotas','Embalse de Escales y Red de Senderos del Valle de Boí periurbano','Capital de comarca que ejerce de base para el montañismo y el turismo de románico. Cuenta con una planta de casas rurales tradicionales y hostales de montaña que eliminan el límite de peso en el 40% de su oferta. Las orillas naturales del embalse sirven como excelentes playas continentales de aguas cristalinas ideales para el refresco canino en verano. Normativa: Normativa de la comarca orientada al agroturismo. En los senderos periféricos del Parque Nacional de Aigüestortes (zonas periféricas de amortiguación), se exige correa obligatoria para proteger el ganado extensivo bovino y ovino. El Embalse de Escales permite el baño canino controlado en zonas de orilla salvaje.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','mascotas','Parque Fluvial de la Mitjana, Campos Elíseos y Red de Autobuses Autobuses de Lleida','Capital administrativa de la provincia. Su mayor infraestructura es el Parque Fluvial de la Mitjana, un área natural protegida junto al río Segre que cuenta con amplios senderos arbolados idóneos para caminar con perros atados. Dispone de dos pipicanes vallados de gran extensión en el tejido urbano. La planta hotelera del centro de la ciudad acepta mascotas bajo un límite de peso medio (15 kg). Normativa: La Ordenanza Municipal de Convivencia prohíbe el tránsito de perros sueltos en zonas verdes no perimetradas, aplicando sanciones de hasta 300 € por deyecciones no higienizadas. Los autobuses urbanos restringen el transporte a perros pequeños alojados de forma permanente en transportín rígido. Obligatorio el censo por ADN canino para residentes.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25183','mascotas','Rutas de Rafting del Río Noguera Pallaresa y Alojamientos de Turismo Activo','Gran polo de atracción nacional para los deportes de aventura en el Pirineo. Destaca por poseer hoteles de gran capacidad y campings de montaña que ofrecen servicios específicos como zonas de lavado para perros tras las caminatas y recintos vallados para el esparcimiento libre. La hostelería local cuenta con terrazas y comedores rústicos con una excelente aceptación de mascotas. Normativa: Normativas locales de turismo activo muy integradoras. Las empresas de aventura permiten la estancia de mascotas en sus centros logísticos de río (algunas ofrecen balsas de rafting adaptadas en tramos familiares de aguas tranquilas). Uso de correa obligatorio en el casco histórico medieval. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','mascotas','Red de Senderos "Aran Culturau", Ribera del Río Garona y Sello Destino Familiar Pet-Friendly','Uno de los grandes epicentros del turismo de nieve y montaña en el sur de Europa con mentalidad totalmente adaptada a las mascotas. Los senderos fluviales del Garona que cruzan el casco urbano están acondicionados con expendedores de bolsas y fuentes mixtas. Prácticamente la mitad de los restaurantes, asadores tradicionales y cafeterías de Vielha permiten el libre acceso de perros educados al interior de sus comedores, proporcionando mantas y Turismo con mascotas cuencos de agua, lo que consolida un ecosistema turístico ideal para las familias. Con este bloque finaliza la auditoría de la provincia de Lleida. ¿Procedemos a continuar de forma masiva con la última provincia de Cataluña, Tarragona (Costa Dorada y Delta del Ebro). Normativa: La normativa ambiental de la sindicatura del Valle de Arán exige el uso de correa en bosques de alta montaña para proteger especies protegidas como el urogallo o el oso pardo. Sin embargo, el municipio es pionero en la hospitalidad comercial: se exime del límite de peso a las mascotas en más del 55% de la planta hotelera local y apartamentos alpinos.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90047','mascotas','Playa de la Platjola','Destino costero situado en el límite sur de Cataluña. La Platjola destaca por ser una playa virgen integrada en un entorno natural con suelo de cantos rodados y grava fina, lo que garantiza un alto nivel de higiene y un oleaje moderado ideal para el baño canino. Carece de servicios premium urbanos como duchas, pero dispone de papeleras de reciclaje. La planta de campings de los alrededores muestra una excelente tolerancia sin límites estrictos de peso. Normativa: Ordenanza de Playas regula de forma permanente y exclusiva el uso de la Playa de la Platjola para el acceso y baño de perros durante todo el año. Fuera de este tramo acotado, la presencia de animales en arenales urbanos acarrea Turismo con mascotas sanciones de hasta 300 €. Uso de correa obligatorio en los accesos naturales.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43038','mascotas','Playa Canina de la Riera d''Alforja y Red de Parques de Esparcimiento','Gran polo de turismo familiar en la Costa Dorada. Su playa canina cuenta con un suelo mixto de arena fina y piedras pequeñas, equipada con una ducha canina adaptada de agua dulce y fuentes a doble altura. El municipio cuenta con áreas de socialización canina cerradas en los parques urbanos del Pinaret y de las動 (del Pescador) provistas de circuitos ágiles básicos. Los apartamentos vacacionales Turismo con mascotas y el sector hotelero local admiten mascotas medianas aplicando un suplemento estándar por estancia. Normativa: La Ordenanza Municipal híperexige la recogida inmediata de deyecciones e impone multas de hasta 400 € por negligencias higiénicas. El tramo de la Riera d''Alforja está acotado con vallas de seguridad de madera y operativo los 365 días del año. Los perros deben transitar atados por el paseo marítimo peatonal y ciclista.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43901','mascotas','Playa de la Bassa de l''Arena y Senderos del Parque Natural del Delta del Ebro','Destino ecoturístico de primer orden y alta demanda internacional para amantes de la naturaleza. La playa de la Bassa de l''Arena ofrece más de 500 metros lineales de arena finísima y aguas completamente someras y tranquilas, ideales para perros de todas las edades, representando uno de los mayores recursos salvajes de litoral de la provincia. La oferta de alojamiento descansa en casas rurales independientes y campings que eximen del límite de peso a las mascotas. Normativa: Las directivas ambientales del Parque Natural del Delta del Ebro prohíben estrictamente la suelta libre de perros en zonas de dunas protegidas y lagunas para salvaguardar la nidificación de las aves acuáticas endémicas. Se autoriza la permanencia de perros sueltos exclusivamente dentro del gigantesco espacio acotado de la playa de la Bassa de l''Arena.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43131','mascotas','Playa Canina de la Punta de la Guineu (Roc de Sant Gaietà)','Destino costero pintoresco que destaca por el singular núcleo del Roc de Sant Gaietà. Su pequeña cala canina ofrece un entorno de arena fina y aguas mansas muy resguardado de las corrientes, contando con pasarelas de acceso y contenedores específicos. La hostelería local y los restaurantes con terrazas orientadas al mar muestran un nivel de tolerancia intermedio, facilitando espacios sombreados confortables para familias que viajan con perros medianos. Normativa: El Ayuntamiento autoriza el acceso con mascotas de forma permanente a la zona delimitada de la Punta de la Guineu. Queda estrictamente vetado el acceso a las playas de la Costa Dorada central adyacentes en temporada alta veraniega bajo sanciones graves. Los hoteles y complejos residenciales locales imponen un límite medio fijado en los 12-15 kg por mascota.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','mascotas','Playa del Miracle (tramo canino estacional) y Red de Autobuses EMT Tarragona','Gran capital histórica y arqueológica de la provincia. Cuenta con un tejido urbano provisto de parques dotados de pipicanes vallados y fuentes adaptadas. La planta de hoteles de cadenas urbanas acepta mascotas bajo un estándar medio de peso (15 kg), operando en sintonía con una red de terrazas comerciales peatonales y restaurantes en la Plaza de la Font que muestran un alto nivel de hospitalidad con las familias con perro. Con este bloque finaliza la auditoría de la comunidad autónoma de Cataluña. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Comunidad Valenciana (comenzando por la provincia de Alicante). ¿Procedemos a iniciar el bloque de municipios pet-friendly de la Comunidad Valenciana? Elige una opción si deseas continuar: • Iniciar la provincia de Alicante (Costa Blanca, Dénia, Altea y Playas Caninas premium). Normativa: La Ordenanza Municipal de la EMT Tarragona autoriza el acceso de perros a las líneas urbanas de autobuses siempre que viajen de forma obligatoria en transportines cerrados o bolsos homologados. Obligatoriedad estricta de diluir las Turismo con mascotas micciones caninas con agua jabonosa en el casco histórico romano bajo multas de hasta 150 €. El tramo de la Playa del Miracle se habilita para el acceso canino fuera de la temporada alta de baño humano.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','mascotas','Playa de Agua Amarga (Doggy Beach) y Red de Parques Caninos','Gran polo de atracción internacional y una de las playas caninas urbanas mejor equipadas de España. Agua Amarga cuenta con arena fina, limpieza de cribado diaria, vallas de seguridad, duchas caninas de agua dulce, fuentes a doble nivel, un chiringuito adaptado que vende snacks para perros y plataformas con sombrillas exclusivas. El tejido urbano dispone de grandes parques con amplias áreas de socialización valladas y una planta hotelera céntrica de cadenas internacionales que elimina los límites de peso en habitaciones seleccionadas. Normativa: La Ordenanza Municipal de Playas regula la Playa de Agua Amarga de forma exclusiva y permanente para perros todo el año. Se permite la suelta y baño libre dentro del perímetro señalizado. En el resto de playas urbanas (Postiguet, San Juan) la presencia canina está estrictamente prohibida en temporada alta bajo sanciones de hasta 600 €. El transporte en autobuses urbanos (TAM) restringe el acceso a perros de menos de 10 kg en transportín cerrado.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03004','mascotas','Playa Canina de Mar y Montaña (Cala de la Solsida) y Casco Antiguo Peatonal','Destino costero de gran valor estético y bohemio. Su playa para mascotas ofrece un entorno natural de cantos rodados, roca y aguas hipercristalinas, ideal para el buceo canino, contando con señalización clara pero careciendo de duchas de agua dulce. Las empinadas calles peatonales del casco histórico son muy transitadas por familias con perros. Las tabernas y restaurantes con miradores orientados al mar muestran un excelente índice de aceptación en sus terrazas. Normativa: Ordenanza específica habilita de forma fija la Cala de la Solsida para Turismo con mascotas el acceso y baño de mascotas los 365 días del año. Uso de correa obligatorio en los senderos de acceso naturales y en todo el núcleo urbano monumental. Sanciones por no diluir las micciones en fachadas históricas de hasta 150 €. Los hoteles boutique aplican un límite de peso medio fijado en los 12-15 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03010','mascotas','Red de Apartamentos Turísticos del Litoral y Senderos Periurbanos del Peñón de Ifach','Destino costero tradicional de fuerte impacto residencial internacional. Su Turismo con mascotas infraestructura pet-friendly descansa principalmente en el sector privado, con una altísima densidad de chalets independientes y bloques de apartamentos turísticos de alquiler que permiten mascotas medianas y grandes bajo fianza. La restauración del paseo marítimo ofrece una tolerancia intermedia, concentrando la aceptación de perros exclusivamente en las mesas exteriores de sus terrazas cubiertas. Normativa: La normativa municipal prohíbe de forma taxativa el acceso de animales a la arena de sus playas principales (Fossa, Arenal-Bol) durante todo el año, no disponiendo actualmente de tramo canino oficial en su término. En el Parque Natural del Peñón de Ifach los perros deben transitar estrictamente atados y con correa corta para proteger la flora y avifauna.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03014','mascotas','Playa Canina de la Escollera Norte y Red de Parques de Esparcimiento','Nodo portuario y gastronómico clave de la Costa Blanca. La playa canina autorizada cuenta con un suelo mixto de arena fina y algas (posidonia) según las corrientes del puerto, equipada con pasarelas de acceso y contenedores de residuos específicos. El municipio cuenta con áreas de socialización canina cerradas en el núcleo urbano. El sector de la restauración destaca por una excelente acogida en terrazas amplias, facilitando cuencos de agua limpia. Normativa: El Ayuntamiento autoriza un tramo específico de unos 100 metros en la zona de la Escollera Norte durante la temporada estival alta. Los animales deben permanecer atados hasta entrar al recinto señalizado. Sanciones por defecación sin recogida de hasta 300 €. Los hoteles de la zona de Les Marines imponen suplementos fijos de limpieza por estancia.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03015','mascotas','Playa Canina de Punta del Riu Sec, Playa de la Barranc d''Aigües y Parques Caninos Urbanos','Gran referente nacional para el turismo con mascotas. La playa de la Punta del Riu Sec ofrece un suelo de cantos rodados y arena gruesa en la desembocadura del río, equipada con pasarelas de madera, papeleras de reciclaje y una ducha canina adaptada de agua dulce. El municipio complementa esto con un parque canino urbano vallado de grandes dimensiones dotado de circuito de agilidad completo. La planta de apartamentos vacacionales muestra una de las normativas de admisión más flexibles de la comarca. Con este bloque finaliza la auditoría de los primeros municipios de la provincia de Alicante. ¿Procedemos a avanzar de forma masiva con el siguiente bloque de Alicante (Municipios de la L a la Z, incluyendo Santa Pola, Torrevieja y Altea). Normativa: Municipio pionero en la provincia con dos recursos de litoral operativos de forma permanente los 365 días del año. Se permite la permanencia de perros sueltos tanto en la arena como en el agua dentro de los recintos señalizados. Obligatoriedad de portar la cartilla sanitaria al día y multas de hasta 400 € por negligencias higiénicas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03020','mascotas','Playa Canina de El Moncayo (Tramo Norte) y Entorno de las Dunas de Guardamar','Destino costero de perfil naturalista y residencial. Su playa para mascotas ofrece un entorno amplio de arena fina dorada y oleaje Turismo con mascotas intermedio, contando con pasarelas de acceso y contenedores de residuos, aunque no dispone de lavapiés caninos urbanos de agua dulce. La oferta hotelera y de apartamentos vacacionales muestra una aceptación intermedia, concentrando el impacto en familias con perros medianos. Normativa: La Ordenanza de Playas habilita de forma permanente un tramo acotado en la zona norte de El Moncayo. Prohibido taxativamente que los perros transiten sueltos o entren en la arena de las playas del casco urbano (Centro, La Roqueta) en época estival, bajo sanciones de hasta 300 €. En el entorno forestal de las Dunas el uso de correa es obligatorio para proteger el ecosistema de fijación litoral.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03035','mascotas','Calamajor / Playa Canina de Cal Bou (Playa de la Calera) y Parques Urbanos','Un icono indiscutible del turismo con mascotas en la Costa Blanca. La playa canina de Cal Bou cuenta con suelo de arena fina, aguas transparentes y tranquilas resguardadas por escolleras, limpieza de filtrado diario, valla de seguridad perimetral, pasarelas de madera, bancos de sombra para los dueños y múltiples duchas caninas de agua dulce de uso libre. La planta hotelera local y los chiringuitos del frente costero registran un alto nivel de adaptación comercial, facilitando el acceso interior de perros educados. Normativa: Ordenanza hiperpermisiva específica que regula de manera definitiva la playa canina permanente mejor valorada de la provincia de Alicante. Permite la libre suelta y el baño de los perros en todo el recinto delimitado los 365 días del año. Obligatorio portar la cartilla sanitaria oficial. Sanciones rigurosas de hasta 500 € por no recogida de deyecciones higiénicas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03038','mascotas','Cala del Moro, Cala Rocío y Parque de la Estación (Pipicán Grande)','Gran polo de turismo residencial nacional e internacional. Las dos calas habilitadas ofrecen un entorno salvaje de roca y agua cristalina ideal para el refresco canino y la práctica de snorkel en pareja, estando equipadas con señalización y papeleras específicas. El Parque de la Estación dispone de una zona de esparcimiento canino vallada de gran tamaño provista de circuito ágil. El sector inmobiliario de alquiler turístico destaca por no aplicar restricciones severas de peso en villas y bungalows independientes. Normativa: El Ayuntamiento regula dos calas de roca naturales de forma permanente (Cala del Moro y Cala Rocío) exclusivas para el acceso con mascotas todo el año. Prohibido el ingreso canino en las playas de arena principales (La Mata, El Cura) durante la temporada alta estival, con multas de hasta 400 €. Obligatorio portar botella para limpiar micciones.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03039','mascotas','Playa Canina de El Charco y Paseo del Río Amadorio','Pintoresco destino costero caracterizado por sus fachadas de colores. Su playa canina ofrece un entorno natural tranquilo de suelo mixto (arena gruesa, grava y cantos rodados) dotado de valla de seguridad básica y contenedores de residuos. El paseo que acompaña los últimos metros del Río Amadorio es una zona verde muy concurrida por familias con perros. Los restaurantes del centro tradicional muestran una alta tasa de aceptación en sus terrazas exteriores protegidas. Con este bloque finaliza el análisis técnico y de infraestructuras de la provincia de Alicante. ¿Procedemos a avanzar de forma masiva con el bloque correspondiente a la provincia de Castellón, continuando el orden alfabético estricto de la Comunidad Valenciana? Elige una opción si deseas continuar: • Continuar con la provincia de Castellón (Costa del Azahar, Vinaròs, Alcossebre y Playas Caninas). Normativa: Ordenanza de Playas autoriza de manera fija la zona sur de la Playa de El Charco como espacio apto para mascotas. Se exige mantener al animal controlado con correa hasta llegar al espacio acotado. Sanciones por defecación sin recogida de hasta 300 €. Los hoteles de la zona aplican un límite de peso medio que promedia los 15 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12027','mascotas','Playa Canina de Aiguaoliva y Red de Establecimientos del Centro Urbano','Nodo portuario y comercial. La playa de Aiguaoliva ofrece un entorno rústico compuesto por cantos rodados, ideal para el refresco de las mascotas, aunque carece de duchas de agua dulce específicas. La hostelería del centro histórico y de la zona del puerto deportivo cuenta con una densidad moderada de terrazas que facilitan sombra y recipientes de agua de cortesía para el turismo de proximidad. Normativa: Habilitada de forma permanente la playa en el límite con Vinaròs. Prohibición absoluta de acceso canino a las playas urbanas (Morrongo, La Caracola) durante la temporada estival bajo sanciones graves. El transporte urbano restringe el acceso a perros que superen los 10 kg en transportín rígido.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12077','mascotas','Playa Canina de Belcaire','Destino de perfil residencial vacacional. La playa de Belcaire destaca por ser una playa de suelo mixto (arena gruesa y cantos rodados) situada junto a la desembocadura del río Belcaire, dotada de pasarelas de acceso y contenedores específicos de residuos caninos. La planta de apartamentos turísticos de segunda línea muestra una excelente tolerancia, absorbiendo el impacto del turismo familiar de fin de semana. Normativa: Ordenanza de Playas regula de forma permanente y exclusiva el uso de la Playa de Belcaire para el acceso y baño de perros durante todo el año. Fuera de este tramo acotado, la presencia de animales en arenales urbanos acarrea sanciones de hasta 300 €. Uso de correa obligatorio en los accesos de madera.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11018','mascotas','Playa de Aiguaoliva, Cala de les Llanetes y Red Comercial Local','Gran referente del litoral mediterráneo para el turismo con mascotas. La Cala de les Llanetes destaca por su espectacular entorno de acantilados, suelo de grava y cantos rodados, limpieza higiénica diaria y aguas hipercristalinas ideales para el baño canino. El municipio complementa sus recursos de litoral con una red comercial urbana hiperpermisiva y una planta hotelera que ofrece kits de bienvenida avanzados, facilitando la integración absoluta de las familias con perro. Con este bloque finaliza la auditoría de los puntos con mayor densidad de servicios de la provincia de Castellón. ¿Procedemos a iniciar de forma masiva el bloque de la provincia de Valencia para completar la Comunidad Valenciana? Elige una opción si deseas continuar: • Continuar con la provincia de Valencia (Capital, Gandía, Pinedo y Playas Caninas). Normativa: Municipio líder y pionero absoluto en la provincia con dos recursos de Turismo con mascotas litoral operativos de forma permanente los 365 días del año. Se permite la permanencia de perros sueltos tanto en la arena como en el agua dentro de los recintos señalizados. Obligatoriedad de portar la cartilla sanitaria al día y multas de hasta 400 € por deyecciones no higienizadas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46204','mascotas','Playa Canina de El Puig (Playa de la Torreta-Santa Elvira)','Gran polo de atracción para el turismo familiar de proximidad. Su playa para mascotas está considerada una de las mejores de la. Normativa: Ordenanza de Playas pionera en la comarca de L''Horta Nord que habilita un espacio permanente de más de 700 metros lineales para el uso recreativo de perros todo el año. Se permite la permanencia sin correa y el baño libre exclusivamente dentro del recinto señalizado. Obligatorio portar la cartilla sanitaria con los tratamientos vigentes actualizados.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46131','mascotas','Playa Canina de Gandia (PlatjaCan) y Red de Espacios Verdes Urbanos','Uno de los grandes motores turísticos de la provincia. La PlatjaCan destaca por su suelo de arena fina dorada, sus aguas limpias y un equipamiento premium que incluye postes para atar a los animales, servicio de bolsas higiénicas, contenedores específicos y personal municipal de asistencia. La planta hotelera local ha desarrollado programas integradores que aceptan perros de hasta 20 kg, complementados por una gran oferta de chiringuitos y terrazas en el sector del puerto muy receptivos con las mascotas. Normativa: El Ayuntamiento regula un tramo de la Playa de l''Ahuir (PlatjaCan) exclusivamente durante la temporada estival alta (junio a septiembre). Queda tajantemente prohibido el tránsito de mascotas por los arenales urbanos del paseo marítimo central bajo multas de hasta 500 €. Los perros deben permanecer controlados y atados fuera de la zona de baño balizada. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35014','mascotas','Red de Alojamientos del Litoral, Eurocamping Oliva y Senderos del Parque Natural del Marjal de Pego-Oliva','Destino costero de perfil residencial y deportivo. Su infraestructura pet-friendly descansa principalmente en su planta de alojamientos privados y campings de primer nivel, que eximen de límites estrictos de peso en sus parcelas y zonas comunes acotadas. El sector de la restauración del paseo marítimo muestra una tolerancia consolidada en Turismo con mascotas terrazas exteriores protegidas del sol, proporcionando recipientes de agua de cortesía. Normativa: La ordenanza municipal prohíbe el acceso de perros a la arena de sus extensas playas de dunas durante la temporada de baño alta por motivos de protección de la fauna litoral. En el entorno protegido del Marjal el tránsito debe realizarse estrictamente con correa corta. Los campings y complejos de bungalows de la zona costera destacan por admitir mascotas aplicando suplementos fijos por noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','mascotas','Playa Canina de Pinedo, Jardín del Turia (Red de Parques Caninos) y EMT Valencia','Gran capital cultural y metropolitana con una inigualable infraestructura verde. El Jardín del Turia (antiguo cauce del río) ofrece kilómetros de senderos arbolados ininterrumpidos que cruzan la ciudad, equipados con múltiples zonas de socialización canina valladas de más de 1.000 m², fuentes a doble altura y circuitos ágiles. La playa de Pinedo cuenta con arena fina, limpieza diaria reforzada, mangueras de agua dulce y vallas perimetrales. El sector hotelero urbano boutique y de grandes cadenas internacionales lidera las políticas de inclusión, ofreciendo estancias totalmente adaptadas y admitiendo perros grandes sin discriminación de peso en habitaciones seleccionadas. [1, 2, 3] Turismo con mascotas Con este bloque finaliza la auditoría de la Comunidad Valenciana. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Extremadura (comenzando por la provincia de Badajoz). ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de Extremadura? Elige una opción si deseas continuar: • Iniciar la comunidad de Extremadura (Provincia de Badajoz, Playas Fluviales con Bandera Azul y Mérida). Normativa: La normativa de transporte local de la EMT Valencia permite el acceso de perros de hasta 15 kg a las líneas de autobuses urbanos portando el "Título EMT Mascota" y viajando dentro de un transportín homologado. Obligatoriedad estricta de censado genético por ADN canino y portar botella de agua con detergente neutro para limpiar las micciones bajo multas de hasta 150 €. El Ayuntamiento regula de forma permanente un tramo de la Playa de Pinedo durante el verano.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90474','mascotas','Embalse de Alange y Rutas del Entorno Arqueológico y Termal','Destino extremeño que combina el turismo de salud, arqueología y naturaleza. El embalse ofrece amplias zonas de orilla de fácil acceso y aguas tranquilas donde las familias acuden a refrescarse con sus mascotas. El sector privado local, compuesto principalmente por casas de turismo rural y apartamentos independientes, destaca por su buena flexibilidad, aceptando perros medianos y grandes bajo suplementos de limpieza moderados. Normativa: La Ordenanza de Convivencia autoriza el acceso de perros atados a los senderos paisajísticos que bordean el embalse. El baño de mascotas está estrictamente prohibido en las zonas de playa urbana acotadas para humanos en verano, derivándose el uso recreativo canino a los tramos de orilla natural libre. Sanciones por deyecciones no retiradas de hasta 200 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','mascotas','Parque del Río Guadiana y Zonas de Esparcimiento de San Fernando','Núcleo urbano fronterizo con un notable desarrollo de su infraestructura verde lineal. Su mayor recurso es el Parque del Río Guadiana, Turismo con mascotas un gran corredor verde acondicionado con amplios senderos peatonales y praderas de césped ideales para pasear con perros atados, provisto de áreas de socialización canina cerradas de uso libre. La planta de hoteles urbanos céntricos acepta mascotas bajo un estándar medio de peso (15 kg), concentrando la hostelería su apertura en amplias terrazas exteriores. Normativa: Ordenanza Municipal de Tenencia de Animales prohíbe la suelta libre de perros en zonas verdes urbanas generales fuera de los recintos vallados. El transporte urbano colectivo limita el acceso exclusivamente a perros de asistencia y mascotas pequeñas en transportín rígido. Obligatorio el control de documentación sanitaria al día.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','mascotas','Parque del Albarregas, Paseo Fluvial del Guadiana y Hoteles de Conectividad Monumental','Gran capital monumental de relevancia internacional que compensa el veto interior de sus ruinas con un extraordinario urbanismo peatonal verde. Destaca el parque lineal que acompaña al río Albarregas y las praderas del río Guadiana bajo los puentes romanos, equipados con pipicanes vallados de gran extensión y fuentes a doble nivel. La planta hotelera del centro histórico y de los accesos principales muestra una gran adaptación comercial, eliminando las Turismo con mascotas restricciones severas de peso en habitaciones seleccionadas para acoger al turismo familiar cultural. Normativa: Normas locales estrictas enfocadas a la protección del conjunto arqueológico de la capital autonómica: prohibido terminantemente el acceso de mascotas al interior de los recintos arqueológicos cerrados (Teatro, Anfiteatro, Museo Romano), permitiéndose el tránsito visual exterior con correa por los parques arqueológicos abiertos. Sanciones por micciones no lavadas en entornos históricos de hasta 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06097','mascotas','Playa Canina del Embalse de Orellana (Zona de los Calicantos)','Uno de los grandes referentes nacionales para el turismo estival de interior con perro. La zona canina habilitada (Calicantos) ofrece un suelo de arena gruesa y piedra fina con aguas hipercristalinas excelentes para el baño recreativo, contando con vallas de seguridad de madera, pasarelas de acceso, papeleras de reciclaje y señalización técnica clara. Los campings y alojamientos rurales del entorno comarcal de La Serena operan de manera muy integradora con políticas laxas de peso y raza, facilitando la pernoctación de familias con mascotas grandes. Con este bloque finaliza la auditoría de los focos clave de la provincia de Badajoz. Siguiendo el orden jerárquico de la comunidad extremeña, la siguiente provincia a auditar es Cáceres (comenzando por Plasencia, Trujillo, Valle del Jerte y su capital). Turismo con mascotas ¿Procedemos a iniciar el bloque de la provincia de Cáceres para completar Extremadura? Elige una opción si deseas continuar: • Continuar con la provincia de Cáceres (Valle del Jerte, Gargantas de la Vera, Cáceres Capital). Normativa: Ordenanza municipal pionera en Extremadura al regular un espacio oficial permanente para el uso de mascotas en el Embalse de Orellana (famoso por poseer Bandera Azul en su tramo humano). Se autoriza la permanencia de perros sueltos tanto en la orilla como dentro del agua en la zona acotada. Obligatorio mantener el control visual del animal y portar la cartilla sanitaria al día.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','mascotas','Parque del Príncipe, Parque de la Consulta y Red de Hoteles Urbanos','Ciudad Patrimonio de la Humanidad con un urbanismo peatonal idóneo para el paseo. Su principal pulmón verde es el Parque del Príncipe, que cuenta con una extensa zona de esparcimiento canino vallada, equipada con fuentes de doble nivel y circuitos básicos de agilidad. La planta hotelera del centro urbano acepta mascotas bajo un estándar medio de peso (15 kg), operando en sintonía con una red de terrazas comerciales en la Plaza Mayor muy receptivas con el turismo de proximidad. Normativa: La Ordenanza Municipal de Tenencia de Animales prohíbe el tránsito de perros sueltos en el recinto monumental intramuros, con sanciones por deyecciones no higienizadas de hasta 300 €. Los autobuses urbanos limitan el acceso a perros pequeños dentro de su transportín homologado. Obligatorio el uso de correa corta de un máximo de 1,5 metros. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','mascotas','Geoparque Villuercas-Ibores-Jara y Red de Alojamientos Rurales de la Puebla','Destino monumental e histórico muy demandado por el turismo familiar y cultural de fin de semana. Sirve como base logística para realizar rutas de senderismo por el entorno protegido del Geoparque Mundial de la UNESCO, el cual cuenta con kilómetros de pistas accesibles con perros. La hostelería de la Plaza de Santa María destaca por sus asadores y Turismo con mascotas mesones tradicionales con terrazas amplias que facilitan cuencos de agua limpia. Normativa: Normas locales estrictas orientadas a la protección del conjunto monástico monumental: prohibido terminantemente el acceso de mascotas al interior del Real Monasterio de Santa María de Guadalupe. El tránsito por las calles medievales empedradas debe realizarse con correa obligatoria. Los alojamientos rurales de los alrededores eliminan el límite de peso en el 40% de su oferta.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10107','mascotas','Garganta de los Infiernos (Zonas periféricas), Charco del Candilejo y Alojamientos Ecoturísticos','Epicentro del ecoturismo y del turismo activo estival en el norte de Extremadura. El municipio ofrece playas fluviales naturales de aguas hipercristalinas ideales para el refresco de las mascotas. El sector privado de la comarca (casas rurales independientes, campings y bungalows) lidera las políticas integradoras al eliminar por completo los límites de peso de las mascotas y facilitar terrenos cerrados independientes para las familias con perros grandes. Normativa: La normativa de la Reserva Natural de la Garganta de los Infiernos prohíbe estrictamente la suelta de perros y el baño canino en las marmitas gigantes de "Los Pilones" por motivos de conservación medioambiental. Se autoriza el baño libre y recreativo en zonas fluviales no acotadas del río Jerte a su paso por el municipio, como el Charco del Candilejo. Uso de correa obligatorio en senderos forestales.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','mascotas','Red de Hoteles Monumentales, Palacio de Chaves y Rutas de los Conquistadores Turismo con mascotas','Nodo turístico cultural de primer orden. Destaca por poseer una planta alojativa señorial que facilita la pernoctación de familias con mascotas medianas, proporcionando alfombras caninas y comederos. El amplio espacio de la Plaza Mayor es ideal para pasear con perros atados, concentrando una alta densidad de restaurantes y mesones con soportales y áreas exteriores cubiertas que muestran una excelente hospitalidad. Con este bloque finaliza la auditoría de la comunidad autónoma de Extremadura. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es Galicia (comenzando por la provincia de A Coruña). ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de Galicia? Elige una opción si deseas continuar: • Iniciar la comunidad de Galicia (Provincia de A Coruña, Playas Caninas del Atlántico y Santiago). Normativa: Normas municipales de convivencia exigen el uso obligatorio de correa en todo el núcleo histórico. Queda prohibido el uso de fuentes públicas ornamentales por animales bajo riesgo de sanción de 150 €. Los hoteles boutique instalados en antiguas casas palacio permiten mascotas medianas aplicando un suplemento estándar de limpieza por noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','mascotas','Playa Canina de Ares (entorno metropolitano) y Red de Parques de Esparcimiento (Parque de Bens)','Gran capital atlántica con una infraestructura verde urbana muy notable. Su principal recurso es el Parque de Bens, un inmenso pulmón verde que cuenta con un área de esparcimiento canino vallada de más de 2.000 m² con circuitos ágiles. Turismo con mascotas La planta de hoteles de cadenas urbanas acepta mascotas bajo un límite de peso medio (15 kg). Las terrazas del paseo marítimo y de la Plaza de María Pita muestran un alto nivel de hospitalidad. Normativa: La Ordenanza Municipal de Playas prohíbe taxativamente la estancia de perros en la arena de los principales arenales urbanos (Riazor, Orzán, Matadero) durante la temporada alta estival (junio a septiembre). Se permite el acceso libre y sin correa en horarios nocturnos acotados (de 22:00 a 08:00) fuera de la época estival alta en zonas periféricas. Los autobuses urbanos limitan el tránsito a perros pequeños dentro de su transportín homologado.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','mascotas','Playa Canina de Ares (Tramo de la Playa de Estacas)','Gran referente del turismo costero pet-friendly en las Rías Altas. La playa canina ofrece un entorno excelente de arena fina y aguas tranquilas resguardadas de las fuertes corrientes del Atlántico, contando con pasarelas de acceso, papeleras de reciclaje específicas y mantenimiento higiénico diario. La planta de apartamentos turísticos locales y campings de los alrededores destaca por su flexibilidad, eliminando el límite de peso en el 40% de su oferta. Normativa: Ordenanza de Playas pionera y de las más permisivas de la provincia, habilitando de forma permanente y exclusiva el tramo final de la Playa de Estacas para el acceso y baño de perros durante todo el año. Se autoriza la permanencia de perros sueltos tanto en la arena como en el agua dentro de la zona señalizada. Sanciones por no recogida de excrementos de hasta 400 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','mascotas','Playa Canina de la Concha (A Laxe) y Senderos del Estuario del Anllóns Turismo con mascotas','Destino costero integrado en la Costa da Morte, ideal para el turismo de naturaleza. Su playa para mascotas ofrece un suelo de arena fina combinado con un paisaje de marismas de alto valor ecológico, ideal para caminatas largas, contando con señalización clara. Los alojamientos de tipo casa rural independiente muestran una excelente predisposición sin límites rígidos de peso. Normativa: El Ayuntamiento regula un tramo de la Playa de la Concha de forma fija como espacio apto para mascotas todo el año. Uso obligatorio de correa en los senderos forestales de enlace y accesos. Las normativas de turismo rural exigen mantener el control visual y el comportamiento silencioso de los animales.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','mascotas','Playa Canina de A Torre (Playa de Taragoña)','Destino situado en la Ría de Arousa con un perfil residencial familiar. Su playa canina ofrece un entorno tranquilo de suelo mixto (arena gruesa y pequeñas conchas) dotado de valla de seguridad básica y contenedores de residuos específicos. Los restaurantes tradicionales del centro urbano muestran una excelente acogida en sus terrazas exteriores protegidas, proporcionando recipientes de agua de cortesía. Normativa: Habilitado de forma fija el tramo de la Playa de A Torre para el uso de mascotas los 365 días del año. Queda prohibido el ingreso canino en las playas de arena principales en temporada estival alta bajo sanciones de hasta 300 €. Turismo con mascotas Los hoteles de la zona aplican límites generales de peso fijados en los 12-15 kg.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','mascotas','Red de Parques Urbanos (Parque de Belvís, Alameda) y Alojamientos para Peregrinos','Gran capital espiritual y cultural de relevancia internacional que registra un notable aumento de visitantes que realizan el Camino de Santiago con su perro [Santiagoturismo]. El Parque de Belvís y el Parque de Galeras cuentan con amplias zonas de esparcimiento canino valladas con dobles Turismo con mascotas puertas de seguridad. La planta hotelera del centro urbano y de los accesos principales ofrece habitaciones adaptadas y servicios de guardería canina concertada [Santiagoturismo]. La hostelería de las plazas peatonales destaca por permitir comer acompañado de la mascota de forma habitual en terrazas exteriores e interiores climatizadas [Santiagoturismo]. Con este bloque finaliza el análisis técnico y de infraestructuras de la provincia de A Coruña. ¿Procedemos a avanzar de forma masiva con la provincia de Lugo (Rías Altas, Mariña Lucense y Playas Caninas), continuando el orden alfabético estricto de Galicia? Elige una opción si deseas continuar: • Continuar con la provincia de Lugo (Mariña Lucense, Ribadeo y Playas Fluviales). Normativa: Normas municipales estrictas enfocadas a la protección del patrimonio barroco: prohibido el acceso de perros sueltos o el uso de fuentes históricas por animales en el casco viejo, aplicando multas de hasta 150 € [Santiagoturismo]. El tránsito debe realizarse siempre con correa corta. Los albergues y hoteles del Camino de Santiago disponen de normativas específicas que flexibilizan el acceso de perros de peregrinos [Santiagoturismo].','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','mascotas','Playa Canina de Penouras','Destino costero destacado de la Mariña Lucense. La playa de Penouras ofrece un entorno natural resguardado de suelo mixto (arena fina y afloramientos rocosos), ideal para que los perros naden en charcos intermareales. Carece de servicios urbanos como duchas caninas, pero dispone de papeleras. La planta de apartamentos turísticos vacacionales y campings periféricos muestra una excelente flexibilidad de pesos. Normativa: La Ordenanza Municipal de Playas regula de forma exclusiva y permanente el tramo de la Playa de Penouras para el acceso y baño canino durante todo el año. Prohibido transitar con mascotas sueltas por las playas urbanas colindantes en temporada alta bajo sanciones de hasta 300 €. Uso de correa obligatorio hasta llegar a la arena.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','mascotas','Paseo Fluvial del Río Miño, Muralla de Lugo y Red de Parques Caninos Turismo con mascotas','Capital monumental con un extraordinario urbanismo peatonal y verde. El Paseo Fluvial del Río Miño ofrece kilómetros de senderos ininterrumpidos en plena naturaleza ideales para largas caminatas caninas. El tejido urbano cuenta con el Parque de Rosalía de Castro y el Parque de Frigsa, provistos de pipicanes vallados de gran tamaño con dobles compuertas. La planta hotelera céntrica acepta mascotas de forma generalizada y el sector hostelero del recinto amurallado cuenta con una altísima densidad de terrazas cubiertas. Normativa: Normas de convivencia prohíben la suelta de animales en el adarve de la histórica Muralla Romana, exigiendo correa corta de un máximo de 1,5 metros. El transporte urbano colectivo restringe el acceso de mascotas que superen los 10 kg. Obligatorio el uso de botellas de agua con detergente neutro para limpiar micciones en la vía pública.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','mascotas','Playa Canina de Cabanela y Rutas del Entorno de la ría del Eo','Punto fronterizo clave con Asturias de gran relevancia turística internacional. La playa de Cabanela ofrece un espacio de arena fina y aguas mansas muy seguras para perros pequeños y cachorros. El casco urbano cuenta con un centro comercial abierto con alta tolerancia al acceso interior y hoteles boutique que eliminan el límite de peso. Las terrazas hosteleras del puerto deportivo facilitan un trato excelente y cuencos de agua limpia. Normativa: Habilitada de forma fija la Playa de Cabanela (en el interior de la ría) Turismo con mascotas para el uso recreativo canino todo el año. Normas ambientales estrictas en el Monumento Natural de la Playa de las Catedrales: prohibido terminantemente el acceso de perros a la arena durante la temporada estival alta y Semana Santa por motivos de conservación y masificación.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','mascotas','Playa Canina de Area (tramo regulado) y Senderos del Souto da Retorta','Municipio costero e histórico de perfil residencial familiar. Su playa canina ofrece un arenal de gran calidad con aguas limpias, equipada con contenedores de residuos específicos, Turismo con mascotas sirviendo de gran desahogo en los meses de verano. El sector hotelero local y las casas de turismo rural muestran una flexibilidad intermedia, aceptando perros medianos y grandes bajo suplementos de limpieza fijos por estancia. Normativa: El Ayuntamiento autoriza un tramo delimitado de la Playa de Area exclusivamente para el disfrute y baño con mascotas. Sanciones por defecación sin recogida de hasta 400 € según la ordenanza higiénico-sanitaria. En el espacio natural protegido del Souto da Retorta (eucaliptales gigantes) el uso de correa es estrictamente obligatorio.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','mascotas','Paseo del Río Arnoia, Playas Fluviales del Arnado y Alojamientos Rurales','Gran referente gallego en gestión urbanística sostenible y ecoturismo. Allariz destaca por un entorno fluvial impecable (Paseo del Arnoia y Acearrica) idóneo para el esparcimiento familiar con perro. La planta hotelera y de turismo rural comarcal muestra una flexibilidad absoluta, eliminando el límite de peso en el 45% de sus instalaciones. Los restaurantes y cafeterías del casco histórico peatonal cuentan con amplias terrazas y patios interiores muy habituados a dar servicio a clientes con mascotas. Normativa: La Ordenanza Municipal de Convivencia autoriza el acceso de perros atados a toda la red de parques fluviales urbanos. Se permite el baño de mascotas de forma libre en las zonas de orilla natural del río Arnoia fuera de los espacios estrictamente balizados para el baño humano estival. Uso de correa extensible limitado a un máximo de 2 metros en el casco histórico medieval.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34008','mascotas','Paseo Fluvial del Río Miño, Entorno de las Termas de Outariz y Red de Pipicanes Urbanos','Capital provincial con un extraordinario corredor verde lineal. El Paseo Fluvial del Miño ofrece más de 10 kilómetros de senderos peatonales arbolados ideales para largas caminatas con mascotas. El tejido urbano dispone de grandes parques (como el de las Mercedes o el de San Lázaro) provistos de áreas de socialización canina cerradas con dobles compuertas. Los hoteles céntricos aceptan mascotas bajo un estándar medio de peso (15 kg), concentrando la hostelería local su apertura en amplias terrazas peatonales exteriores. Normativa: La Ordenanza de Tenencia de Animales prohíbe el acceso de perros al interior de las pozas termales públicas o privadas por motivos higiénico-sanitarios, permitiéndose su estancia amarrados en las zonas de césped perimetrales. Los autobuses urbanos restringen el tránsito a perros pequeños dentro de su transportín rígido. Sanciones por deyecciones no retiradas de hasta 300 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','mascotas','Rutas del Vino del Ribeiro, Entorno del Embalse de Castrelo de Miño y Complejos Rurales','Capital histórica del vino Ribeiro con un fuerte perfil enfocado al enoturismo y turismo rural. Las orillas naturales del embalse colindante de Castrelo de Miño funcionan como excelentes playas de interior para el refresco canino controlado. La planta hotelera local (pazos reconvertidos y casas de campo) destaca por su buena flexibilidad, facilitando estancias en parcelas valladas independientes para familias que viajan con mascotas grandes. Normativa: Normas locales exigen el uso obligatorio de correa en todo el barrio judío histórico. El acceso a monumentos cerrados y bodegas tradicionales está regulado bajo estricto derecho de admisión, aunque las rutas exteriores de viñedos son completamente accesibles con mascota. Los alojamientos rurales independientes de la periferia eliminan los límites de peso de forma generalizada.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32052','mascotas','Miradores del Cañón del Sil, Embarcaderos fluviales y Alojamientos de Ecoturismo','Uno de los epicentros turísticos de interior más potentes del norte de España. El municipio destaca por una infraestructura hotelera rural hiperespecializada en familias con perro, ofreciendo fincas valladas y servicios integradores que eliminan cualquier tipo de límite de peso o raza. Los espectaculares miradores como el de "Os Penedos do Castro" o el de "Cabezoás" registran un impacto masivo de turismo familiar con mascotas, operando en sintonía con restaurantes tradicionales de montaña con amplias zonas exteriores sombreadas. Con este bloque finaliza la auditoría de la provincia de Ourense. Siguiendo el orden alfabético estricto de la comunidad gallega, la siguiente y última provincia a auditar es Pontevedra (Rías Baixas, Sanxenxo, Vigo y la mayor densidad de playas caninas de la región). ¿Procedemos a iniciar de forma masiva el bloque de la provincia de Pontevedra para completar Galicia? Elige una opción si deseas continuar: • Continuar con la provincia de Pontevedra (Rías Baixas, Vigo, O Grove y Playas Caninas premium). Normativa: Las directivas de conservación de la Ribeira Sacra exigen llevar a los perros con correa obligatoria por la red de pasarelas y senderos de los cañones para proteger la avifauna protegida y evitar accidentes en zonas escarpadas. Los catamaranes turísticos fluviales que recorren el Sil cuentan con normativas específicas que permiten el Turismo con mascotas acceso de perros atados y con bozal en líneas seleccionadas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','mascotas','Playa Canina de Cunchiña y Senderos de Cabo Home','Destino costero de gran valor natural. Su playa canina ofrece un entorno tranquilo de suelo mixto (arena y pequeñas piedras), ideal para el baño recreativo. La planta de apartamentos turísticos locales y casas rurales de la comarca del Morrazo muestra una excelente flexibilidad de pesos, absorbiendo un alto volumen de turismo familiar que busca rutas de senderismo costero en pareja con su perro. Normativa: La Ordenanza Municipal de Playas habilita de forma permanente la Playa de Cunchiña para el acceso y baño de perros todo el año. Prohibición estricta de acceso de animales a los arenales más turísticos de la península (como Rodeira o Barra) en temporada estival alta, bajo multas de hasta 300 €. Uso de correa obligatorio en los senderos costeros de Cabo Home.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36009','mascotas','Playa Canina de O Espiño, Playa Canina de O Portiño y Red Gastronómica Local','Gran referente nacional para el turismo costero con mascotas. Las playas de O Espiño y O Portiño ofrecen más de 1.000 metros de arena fina y blanca, aguas hipercristalinas y tranquilas resguardadas por dunas, contando con limpieza mecánica y papeleras de reciclaje específicas. La planta de campings de primera categoría de la zona y los hoteles boutique eliminan las restricciones de peso en habitaciones seleccionadas, cooperando con un sector de marisquerías y terrazas portuarias altamente tolerantes. Normativa: Municipio pionero en la regularización del litoral gallego con dos extensas playas caninas consecutivas operativas los 365 días del año de forma exclusiva. Se autoriza la libre suelta y el baño de las mascotas dentro del perímetro señalizado. Sanciones de hasta 400 € por negligencias higiénicas en los paseos marítimos del centro urbano.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','mascotas','Casco Histórico Peatonalizado, Isla de las Esculturas (Illa das Esculturas) y Sello Comercial Local','Modelo internacional de urbanismo peatonal ideal para viajar con mascotas. La Isla de las Esculturas, un inmenso parque lineal a orillas del río Lérez, ofrece kilómetros de praderas y senderos arbolados ideales para largas caminatas. El centro histórico de la ciudad cuenta con la mayor densidad de comercios, librerías, cafeterías de especialidad y tabernas tradicionales de la provincia con acceso interior permitido, consolidando un ambiente familiar plenamente integrado. Normativa: Ordenanza de Convivencia Ciudadana hipervanguardista. Prácticamente todo el núcleo urbano central está peatonalizado, lo que elimina los riesgos de tráfico y facilita el tránsito seguro con correa corta. Los autobuses urbanos limitan el tránsito a perros pequeños dentro de su transportín, pero el modelo peatonal de la ciudad Turismo con mascotas minimiza la necesidad de transporte motorizado. Obligatorio el uso de botellas de agua para limpiar micciones.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','mascotas','Playa Canina de O Espiño (Límite con O Grove) y Alojamientos Vacacionales del Salnés','Capital turística de las Rías Baixas con un fuerte perfil estival. Su infraestructura petfriendly descansa principalmente en el sector privado de la periferia, donde la densidad de chalets independientes, apartamentos turísticos de alquiler vacacional y Turismo con mascotas campings muestra una flexibilidad elevada sin límites estrictos de tamaño. Las terrazas de la zona del puerto deportivo ofrecen una tolerancia intermedia, concentrando el acceso en mesas exteriores protegidas. Normativa: La ordenanza municipal prohíbe taxativamente la estancia de perros en la arena de las playas urbanas principales (Silgar, Baltar) durante la temporada alta de baño, derivándose el uso canino a los arenales compartidos de la periferia. Los hoteles de gran capacidad de primera línea imponen límites estrictos de peso de entre 10 kg y 12 kg, exigiendo suplementos por noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36015','mascotas','Playa Canina de Fuchiños, Playa Canina de A Calzoa y Red de Autobuses Vitrasa','Gran motor socioeconómico de la provincia con una infraestructura pública de litoral consolidada. Las playas caninas ofrecen un suelo de arena fina dorada excelente, limpieza diaria y mangueras de agua dulce, sirviendo de gran desahogo en los meses estivales. El tejido urbano cuenta con parques masivos como el de Castrelos o el monte de O Castro, provistos de pipicanes vallados con elementos ágiles. La planta de hoteles de cadenas urbanas acepta mascotas bajo un estándar medio de 15 kg. Turismo con mascotas Con este bloque finaliza la auditoría de la comunidad autónoma de Galicia. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es La Rioja. ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de La Rioja? Elige una opción si deseas continuar: • Iniciar la comunidad de La Rioja (Logroño, Enoturismo, Rutas del Vino y Parques de interior). Normativa: El Ayuntamiento regula de forma permanente dos tramos de playa contiguos en la zona de Coruxo (A Calzoa y Fuchiños) exclusivos para el uso canino todo el año. La normativa de transporte en Vitrasa permite el acceso a autobuses urbanos únicamente a perros pequeños en transportín rígido cerrado. Obligatoriedad de portar botella de agua para limpiar micciones bajo multas de hasta 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','mascotas','Vía Verde del Oja, Paseo de Tenorio y Hoteles de Montaña','Gran polo de atracción nacional para el turismo de montaña, esquí y escapadas de naturaleza. Ezcaray destaca por la Vía Verde del Oja y el Paseo de Tenorio, dos corredores naturales idóneos para pasear de forma segura con mascotas a orillas del río. La hostelería local cuenta con una altísima densidad de asadores tradicionales y restaurantes con terrazas climatizadas donde se da un trato excelente a las familias con perro, facilitando recipientes de agua limpia. Normativa: La Ordenanza Municipal autoriza el tránsito de perros atados en toda la red de senderos locales. El uso de correa es obligatorio en el interior del casco urbano histórico. Los alojamientos de tipo apartamento turístico y los hoteles rurales de Turismo con mascotas montaña destacan por una baja restricción de peso, eliminando los límites en más del 40% de la oferta.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','mascotas','Barrio de la Estación (Rutas de Enoturismo) y Alojamientos Integrados en Viñedos','Capital del vino de Rioja con un fuerte perfil enfocado al enoturismo. Su infraestructura descansa en una excelente red de alojamientos periféricos y hoteles boutique que ofrecen detalles de bienvenida para las mascotas. El entorno del río Tirón cuenta con senderos aptos para caminar con Turismo con mascotas perros. Los restaurantes de la zona de "El Tubo" tradicional concentran la actividad pet-friendly en terrazas exteriores protegidas. Normativa: Normas locales enfocadas a la preservación de los entornos industriales históricos. Uso de correa obligatorio en todo el Barrio de la Estación. El acceso al interior de las bodegas centenarias y salas de catas está regulado por el derecho de admisión (permitido mayoritariamente en patios exteriores), aunque los hoteles de la comarca admiten mascotas medianas aplicando un suplemento estándar por noche.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','mascotas','Parque del Ebro, Parque de La Grajera y Red de Autobuses Urbanos AULOSA','Capital autonómica con una extraordinaria infraestructura verde. El Parque del Ebro y el Parque de La Grajera ofrecen kilómetros de senderos arbolados periurbanos ininterrumpidos y una amplia zona de esparcimiento canino vallada de gran extensión, equipada con fuentes a doble altura y circuitos ágiles. La planta hotelera de la zona centro acepta mascotas bajo un estándar medio de peso (15 kg), operando en sintonía con las terrazas de la zona monumental de la Calle Laurel y San Juan, altamente hospitalarias. Turismo con mascotas Con este bloque finaliza la auditoría de los focos clave de la comunidad autónoma de La Rioja. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es la Comunidad de Madrid. ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de Madrid? Elige una opción si deseas continuar: • Iniciar la comunidad de Madrid (Capital, Red de Transportes Metro/Cercanías, Pantano de San Juan y Sierra). Normativa: La Ordenanza de Fomento de la Convivencia Ciudadana prohíbe el tránsito de perros sueltos en zonas verdes no delimitadas, aplicando multas de hasta 300 € por deyecciones no higienizadas. Los autobuses urbanos (AULOSA) permiten el acceso a perros pequeños dentro de su correspondiente transportín rígido y cerrado. Obligatorio portar botella de agua para limpiar micciones en la vía pública bajo riesgo de sanción de 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','mascotas','Parque O''Donnell, Paseo del Río Henares y Red de Hoteles de Conectividad Corredor','Ciudad Patrimonio de la Humanidad con un urbanismo peatonal idóneo para pasear en familia. El Parque O''Donnell cuenta con un área canina vallada de gran extensión provista de circuitos ágiles básicos. La planta hotelera y los apartamentos del centro histórico aceptan mascotas medianas aplicando suplementos fijos de limpieza por estancia, mientras que las terrazas de la Plaza de Cervantes muestran una excelente tasa de acogida. Normativa: Ordenanza de Convivencia protege el casco histórico monumental; prohibido llevar perros sueltos o el uso de fuentes públicas por animales bajo multas de hasta 300 €. Turismo con mascotas Obligatorio diluir las micciones con agua. Conexión directa con la Red de Cercanías Madrid, que permite el acceso de perros de todos los tamaños atados y con bozal de forma gratuita.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','mascotas','Red de Metro de Madrid, Red de Cercanías Renfe, Madrid Río y Parque de El Retiro','Gran capital cultural y económica de relevancia mundial con una infraestructura verde urbana de primer nivel. Madrid Río ofrece kilómetros de senderos lineales arbolados a orillas del Manzanares totalmente acondicionados. La planta de hoteles boutique de cinco estrellas y cadenas de gran capacidad (como las marcas Aloft o Ilunion) lidera las políticas "Pet-Inclusion" más avanzadas, eliminando límites de peso y ofreciendo menús específicos para mascotas. Más del 45% de los locales comerciales del centro y las cafeterías de especialidad permiten el libre acceso interior de perros educados. Normativa: La pionera normativa de Metro de Madrid permite el acceso de perros de todos los tamaños con bozal y correa corta en el último coche del tren, restringido únicamente de lunes a viernes en horas punta (de 7:30 a 9:30, de 14:00 a 16:00 y de 18:00 a 20:00). La Red de Cercanías Renfe permite el acceso libre sin límites de peso. La ordenanza municipal autoriza la suelta libre de perros en la red de parques públicos generales (como El Retiro o Juan Carlos I) durante los horarios regulados de invierno (de 19:00 a 10:00) y verano (de 20:00 a 10:00). Sanciones severas de hasta 500 € por deyecciones no recogidas. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','mascotas','Playas Continentales del Pantano de San Juan (Zonas no balizadas)','El gran "mar de Madrid" y principal polo de atracción estival para el turismo de interior con perro en la comunidad. Las orillas naturales del pantano ofrecen excelentes playas de interior rodeadas de pinares ideales para el refresco canino en Turismo con mascotas verano. La infraestructura turística local destaca por una gran oferta de casas rurales independientes, villas y campings que muestran una flexibilidad elevada sin límites estrictos de peso en parcelas valladas. Normativa: Las ordenanzas restringen taxativamente el baño y la presencia canina en los arenales humanos declarados con Bandera Azul (como la Playa de la Virgen de la Nueva) durante la temporada alta estival. Se permite el acceso y refresco de mascotas exclusivamente en los tramos de orilla salvaje y calas rocosas no balizadas de la periferia del embalse. Uso de correa obligatorio en senderos de pinos forestales.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','mascotas','Bosque de la Herrería, Senderos del Monte Abantos y Alojamientos Rurales de la Sierra','Destino monumental e histórico de montaña muy demandado por el turismo familiar y de naturaleza de fin de semana. Ofrece kilómetros de pistas forestales y senderos alpinos completamente accesibles y concurridos por usuarios con perros grandes. La planta hotelera local y las posadas tradicionales de montaña destacan por su buena flexibilidad de pesos, operando en sintonía con una red de asadores tradicionales y restaurantes con terrazas con un trato excelente y cuencos de agua limpia de cortesía. Turismo con mascotas Con este bloque finaliza la auditoría de la Comunidad de Madrid. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Región a auditar es la Región de Murcia. ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de Murcia? Elige una opción si deseas continuar: • Iniciar la comunidad de Murcia (Costa Cálida, Mazarrón, Águilas y Playas Caninas). Normativa: Normas de Patrimonio Nacional y del Parque Nacional obligan a que los perros transiten estrictamente atados en todo el Bosque de la Herrería para proteger el ecosistema y la fauna protegida de la sierra. Prohibido terminantemente el acceso de mascotas al interior del Real Monasterio. Sanciones por micciones no lavadas en entornos históricos de hasta 150 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30003','mascotas','Playa de la Cañada del Negro, Playa de Cala Mijo y Senderos del Cabo Cope','Gran referente del turismo costero pet-friendly en el límite con Andalucía. La playa de la Cañada del Negro destaca por su suelo mixto de arena fina, grava y roca, dotada de pasarelas de acceso, cartelería informativa técnica y servicio de limpieza reforzado. El municipio ofrece un entorno comercial muy abierto, con un sector hotelero y de apartamentos vacacionales que elimina los límites de peso en más del 35% de su oferta habitacional. Normativa: La Ordenanza Municipal de Playas regula de forma permanente y exclusiva dos playas para el acceso y baño de perros los Turismo con mascotas 365 días del año. Los animales pueden permanecer sueltos dentro de las zonas acotadas. Prohibida la entrada a los arenales urbanos principales (Delicias, Colonia) en verano, con multas de hasta 300 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','mascotas','Playa de la Calera (Isla Plana), Playa de Los Alemanes (La Manga) y Red de Parques Caninos','Destino monumental, histórico y costero de gran envergadura. La playa de la Calera ofrece un entorno natural de grava y cantos rodados con aguas muy limpias ideales para el buceo canino. En el núcleo urbano, el parque de esparcimiento Turismo con mascotas de la Cuesta del Batel dispone de un recinto vallado amplio con juegos de agilidad. La planta hotelera del centro administrativo acepta mascotas bajo un estándar medio de peso (15 kg). Normativa: El Ayuntamiento habilita dos espacios litorales fijos permanentes para el disfrute canino. Obligatorio el uso de correa corta de un máximo de 1,5 metros en todo el casco histórico y paseos marítimos de La Manga. Los autobuses urbanos limitan el acceso a perros pequeños metidos de forma obligatoria en su correspondiente transportín homologado.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30026','mascotas','Playa de las Moreras, Playa del Gachero, Playa de Cobaticas y Chiringuitos Adaptados','Uno de los tres grandes iconos del turismo costero familiar con mascotas en España. La Playa de las Moreras es un arenal premium de gran longitud con arena fina y dorada, equipada con pasarelas de madera, mangueras de limpieza canina, fuentes adaptadas a doble altura y limpieza mecánica de filtrado diario. La planta alojativa local (campings de primera categoría y complejos residenciales) y los chiringuitos de primera línea muestran una de las normativas de inclusión comercial más avanzadas de la comarca, permitiendo el acceso interior sin discriminación por tamaño. Normativa: Municipio líder absoluto y pionero en el litoral mediterráneo con tres playas caninas oficiales operativas los 365 días del año de forma permanente. Se autoriza la libre suelta y el baño de los animales dentro de los recintos balizados. Sanciones estrictas de hasta 450 € por negligencias higiénicas fuera de los espacios caninos.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','mascotas','Paseo Fluvial del Río Segura, Parque de Fofó y Red de Autobuses TMP Murcia','Capital autonómica con un notable cinturón verde lineal. El Paseo Fluvial del Río Segura ofrece kilómetros de senderos peatonales arbolados ideales para largas caminatas urbanas con mascotas atadas. El tejido urbano cuenta con múltiples pipicanes vallados de gran tamaño dotados de fuentes adaptadas. La planta de hoteles de cadenas urbanas céntricas acepta mascotas bajo un límite de peso medio (15 kg), concentrando la hostelería su apertura en amplias terrazas peatonales exteriores. Con este bloque finaliza la auditoría de la Región de Murcia. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es la Comunidad Foral de Navarra. ¿Procedemos a iniciar de forma masiva el primer bloque de municipios pet-friendly de Navarra? Elige una opción si deseas continuar: Turismo con mascotas. Normativa: La Ordenanza de Convivencia Ciudadana prohíbe el tránsito de perros sueltos en zonas verdes públicas generales fuera de los recintos acotados, con multas de hasta 300 € por deyecciones no higienizadas. Los autobuses metropolitanos restringen el transporte a perros pequeños en transportín rígido. Obligatorio el censo por ADN canino para residentes.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31050','mascotas','Casco Histórico de Elizondo, Ruta de la Cascada de Xorroxin y Red de Casas Rurales','Gran polo de atracción para el ecoturismo y el senderismo en el norte peninsular. El Valle de Baztan es el epicentro idóneo para realizar rutas masivas en pareja con el perro, destacando el Sendero a la Cascada de Xorroxin o el entorno del Señorío de Bertiz. El sector privado destaca por su extraordinaria hospitalidad, ofreciendo amplios terrenos vallados exteriores en las casas de alquiler íntegro. Los restaurantes tradicionales de Elizondo cuentan con amplias terrazas protegidas y sidrerías que facilitan cuencos con agua limpia. Normativa: Las ordenanzas locales y ambientales del valle exigen llevar a los perros con correa obligatoria en los senderos de los bosques para proteger el ganado extensivo ovino y vacuno de la zona. Se prohíbe que los perros asusten a las reses, bajo sanciones de hasta 300 €. Los alojamientos rurales de tipo caserío tradicional eliminan el límite de peso en más del 60% de su planta habitacional. Turismo con mascotas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33014','mascotas','Parque de la Taconera, Paseo Fluvial del Arga y Red de Autobuses Urbanos (Eskualdeko Garraioa)','Capital autonómica con un extraordinario cinturón verde urbano. Sobresale el Paseo Fluvial del Arga, un corredor natural de más de 12 kilómetros de senderos peatonales arbolados idóneos para caminar de forma segura y realizar ejercicio con mascotas. El tejido urbano cuenta con múltiples parques provistos de pipicanes vallados equipados con fuentes a doble altura. La planta hotelera acepta mascotas bajo un estándar medio de peso (15 kg), operando en sintonía con un sector hostelero en el casco antiguo (alrededores de la Plaza del Castillo) con una alta tasa de aceptación Turismo con mascotas en terrazas exteriores dotadas de sistemas de climatización estacional. Con este bloque finaliza la auditoría de la Comunidad Foral de Navarra. Siguiendo el orden alfabético estricto de la Base de Datos Nacional, la siguiente Comunidad Autónoma a auditar es el País Vasco / Euskadi (comenzando por la provincia de Álava / Araba). ¿Procedemos a iniciar de forma masiva el bloque de municipios pet-friendly del País Vasco? Elige una opción si deseas continuar: • Iniciar la comunidad del País Vasco (Provincia de Álava, Vitoria-Gasteiz Green Capital y Embalses). Normativa: La Ordenanza Municipal de Sanidad y Tenencia de Animales autoriza el esparcimiento de perros sueltos exclusivamente en los horarios y zonas verdes periurbanas debidamente señalizadas por el consistorio. Queda prohibido el acceso a los jardines históricos del centro (interiores de la Taconera) sin correa. Los autobuses urbanos restringen el transporte a perros pequeños alojados de forma permanente en transportín rígido cerrado. Sanciones por defecación sin recogida de hasta 300 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50013','mascotas','Entorno del Embalse de Ullibarri-Gamboa (Playas de interior) y Red de Senderos de la Llanada Alavesa','Gran polo de atracción estival para el turismo familiar de interior y deportivo con perro. El gigantesco Embalse de Ullibarri-Gamboa ofrece una red de playas continentales de aguas tranquilas y limpias idóneas para el refresco de las mascotas. La infraestructura turística local destaca por una excelente oferta de agroturismos tradicionales vascos (caseríos) y campings que eximen del límite de peso en parcelas valladas, facilitando la pernoctación de familias con mascotas grandes. Normativa: Las normativas sanitarias y de uso del Parque Provincial prohíben taxativamente el baño de mascotas en los arenales humanos con Bandera Azul (como Garaio o Landa) en temporada alta. Se autoriza el baño libre y el esparcimiento canino en los tramos de orilla natural salvaje y calas no balizadas del embalse. Uso de correa obligatorio en caminos perimetrales de la Red de Itinerarios Verdes de Álava. Sanciones de hasta 200 € por abandono de residuos.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','mascotas','Rutas de Enoturismo de Rioja Alavesa, Complejo Lagunar de Laguardia y Alojamientos Boutique','Destino monumental y enoturístico de primer nivel que registra una gran afluencia de turismo familiar de proximidad. Su infraestructura descansa en una excelente oferta hotelera de diseño y casas rurales independientes que ofrecen detalles de bienvenida para las mascotas (camas caninas y snacks). El entorno del complejo lagunar cuenta con senderos llanos aptos para caminar de forma segura. Los restaurantes tradicionales y bares de pintxos de la Plaza Mayor y calles peatonales muestran una alta aceptación en sus terrazas exteriores protegidas. Normativa: Normativa de convivencia estricta orientada a la protección del conjunto monumental medieval amurallado. Uso de correa corta de un máximo de 1,5 metros obligatorio en todo el centro histórico peatonal. El acceso al interior de las bodegas subterráneas tradicionales y salas de catas Turismo con mascotas está regulado por el derecho de admisión individual, permitiéndose el tránsito atado por las viñas exteriores. Los hoteles de alta gama aplican suplementos fijos de limpieza que oscilan entre los 15 € y 25 € por estancia.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','mascotas','Anillo Verde (Parque de Salburua, Zabalgana), Red de Autobuses Urbanos TUVISA y Parques Caninos','Galardonada internacionalmente como European Green Capital, es un auténtico referente nacional en infraestructura verde urbana. Su extraordinario Anillo Verde conecta miles de hectáreas forestales periurbanas mediante senderos e itinerarios completamente accesibles e idóneos para caminar de forma segura con mascotas. El tejido urbano cuenta con múltiples áreas de socialización canina cerradas de gran extensión dotadas de circuitos de agilidad profesionales. La planta de hoteles de cadenas urbanas acepta mascotas bajo un estándar flexible de peso (hasta 25 kg), operando en perfecta sintonía con un sector hostelero en el casco viejo medieval con un altísimo índice de aceptación comercial en el interior de locales y cafeterías de especialidad. Con este bloque finaliza la auditoría de la provincia de Álava. Siguiendo el orden alfabético estricto de la comunidad autónoma de Euskadi, la siguiente provincia a auditar es Bizkaia (comenzando por Bilbao, Getxo, Sopela y sus playas caninas costeras). ¿Procedemos a iniciar de forma masiva el bloque de la provincia de Bizkaia? Elige una opción si deseas continuar: • Continuar con la provincia de Bizkaia (Bilbao, Costa Vasca, Getxo y Playas Caninas). Normativa: La Ordenanza Municipal de Tenencia de Animales autoriza el esparcimiento de perros sueltos con control visual en la red general de parques públicos de la ciudad exclusivamente en horarios acotados (de 20:00 a 10:00). Queda estrictamente prohibida la suelta de animales en los jardines históricos del centro (Parque de la Florida) y en las zonas de reserva de fauna del Parque de Salburua para proteger las especies en peligro (como el visón europeo). Los autobuses urbanos (TUVISA) permiten el acceso a perros medianos y grandes siempre que viajen Turismo con mascotas con bozal, correa corta y tarjeta canina de transporte municipal. Sanciones por defecación sin recogida de hasta 300 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','mascotas','Paseo de la Ría del Nervión, Parques Caninos Urbanos, Red de Metro Bilbao y Red de Bilbobus','Gran polo de atracción internacional para el turismo urbano y cultural. El Paseo de la Ría del Nervión ofrece kilómetros de itinerario peatonal ininterrumpido idóneo para pasear en familia con el perro, conectando el Museo Guggenheim con el Casco Viejo. El tejido urbano cuenta con múltiples zonas Turismo con mascotas verdes con áreas de socialización canina valladas que superan los 1.000 m², equipadas con dobles puertas y fuentes adaptadas. La planta hotelera del centro administrativo (hoteles boutique de diseño y cadenas de gran capacidad) lidera las políticas sin límite de peso, ofreciendo alfombras, comederos y obsequios de bienvenida en la habitación. Más del 40% de los comercios y cafeterías de especialidad permiten el libre acceso interior de perros educados. Normativa: La Ordenanza Municipal de Tenencia y Protección de Animales regula de forma avanzada el esparcimiento canino. La red de Metro Bilbao permite el acceso de perros de hasta 8 kg de peso de forma gratuita si viajan en brazos, transportín o bolsa cerrada; los perros guía o de asistencia viajan sin limitaciones de tamaño. Los autobuses urbanos (Bilbobus) limitan el acceso a mascotas pequeñas en transportín rígido. Obligatorio el uso de correa en zonas monumentales del Casco Viejo y Abandoibarra. Sanciones por no recogida de deyecciones de hasta 300 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47008','mascotas','Playas Caninas de Las Arenas y Arrigunaga (tramos estacionales), Puerto Viejo de Algorta y Paseo de La Galea','Destino costero y residencial de perfil señorial y alta demanda familiar. El Paseo de La Galea ofrece kilómetros de senderos sobre acantilados verdes con vistas espectaculares al Cantábrico ideales para largas caminatas con mascotas. El singular núcleo del Puerto Viejo de Algorta cuenta con un urbanismo de callejuelas peatonales empedradas con Turismo con mascotas una altísima densidad de tabernas tradicionales que muestran una excelente tolerancia en terrazas exteriores, facilitando cuencos de agua limpia. La planta de apartamentos turísticos locales destaca por no aplicar restricciones severas de tamaño. Normativa: La Ordenanza Municipal de Playas regula el acceso canino a los arenales. Se permite la estancia de perros en la Playa de Las Arenas y en la Playa de Arrigunaga exclusivamente fuera de la temporada de baño alta (del 1 de octubre al 31 de mayo); de junio a septiembre el acceso está restringido a horarios nocturnos acotados (de 21:00 a 09:00). Conexión directa con la Red de Metro Bilbao que facilita la movilidad. Tránsito con correa obligatorio por el histórico Paseo de las Grandes Villas.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90956','mascotas','Playas Caninas de Atxabiribil y Barinatxe (tramos estacionales) y Rutas de los Acantilados','Epicentro del turismo deportivo, surf y de naturaleza en la costa vizcaína. Las playas de Atxabiribil y Barinatxe ("La Salvaje") ofrecen espacios salvajes inmensos de arena fina y fuerte oleaje muy valorados por los usuarios con perros medianos y grandes. La red de senderos que une los acantilados de Sopela con Plentzia registra un alto volumen de excursiones familiares con mascotas. La oferta hotelera descansa principalmente en hostales de ambiente surfero y apartamentos turísticos privados con una flexibilidad elevada. Normativa: Normas de uso de arenales restringen la presencia canina en temporada de baño estival alta (junio a septiembre), autorizando el acceso libre y sin correa exclusivamente fuera del horario de salvamento (de 20:00 a 10:00). Durante el resto del año, el esparcimiento en la arena es completamente libre. Las escuelas de surf de la zona operan bajo regulaciones comerciales que toleran mascotas de forma habitual en sus recintos.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','mascotas','Barrio de la Marina, Paseo Fluvial de Bidasoa y Alojamientos Monumentales','Pintoresco municipio medieval y marinero fronterizo con Francia de gran Turismo con mascotas demanda turística. Su principal fortaleza reside en el emblemático Barrio de la Marina, caracterizado por sus calles peatonales con casas de balcones coloridos, el cual concentra una gran densidad de tabernas tradicionales y restaurantes con terrazas amplias totalmente adaptadas para el descanso familiar con el perro. La planta de apartamentos turísticos locales y los paradores y hoteles boutique muestran una flexibilidad intermedia aceptando mascotas medianas bajo petición previa. Normativa: Queda estrictamente prohibido el acceso de perros a la arena de la playa urbana principal durante los meses centrales de verano (junio a septiembre). Se permite el tránsito con correa por el paseo marítimo peatonal colindante y senderos perimetrales. Las embarcaciones de recreo y transbordadores fluviales que conectan con Hendaya (Francia) permiten mascotas atadas. Sanciones por deyecciones no higienizadas de hasta 250 €.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21012','mascotas','Parque Ecológico de Plaiaundi, Paseo de Colón y Red de Parques Caninos Urbanos','Eje logístico y comercial clave de la comarca del Bidasoa. El tejido urbano cuenta con múltiples áreas de socialización canina cerradas de gran extensión provistas de dobles puertas de seguridad y fuentes a doble altura adaptadas para mascotas. La planta hotelera enfocada al turismo de paso y de Turismo con mascotas negocios acepta mascotas bajo un estándar medio de peso (15 kg), operando en perfecta sintonía con un sector hostelero en el centro comercial abierto de la ciudad con buena tolerancia en terrazas exteriores peatonales. Normativa: La Ordenanza de Convivencia Ciudadana prohíbe el esparcimiento de perros sueltos en zonas verdes públicas generales fuera de las áreas señalizadas. En el entorno protegido del Parque Ecológico de Plaiaundi los perros deben transitar de forma obligatoria estrictamente atados con correa corta para no perturbar la avifauna y los humedales. Conectividad directa con Renfe Cercanías y Euskotren, que eximen de límites de peso en el transporte ferroviario.','inventario_turismo_mascotas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','mascotas','Playa de Zarautz (Tramo estacional), Biotopo Protegido de Iñurritza y Rutas por los Acantilados','Epicentro del turismo de surf, gastronomía y naturaleza de la Costa Vasca. El extenso paseo marítimo peatonal que bordea la playa registra un altísimo volumen de tránsito de familias con mascotas grandes. Las escuelas de surf y los hostales de ambiente juvenil muestran una flexibilidad elevada. El sector de la restauración (incluyendo conocidos establecimientos tradicionales del centro histórico) destaca por su excelente hospitalidad en amplias áreas exteriores cubiertas, facilitando sombra y recipientes con agua de cortesía. Turismo con mascotas Con este bloque finaliza la auditoría técnica y de infraestructuras de la provincia de Gipuzkoa y, con ello, se completa el análisis del País Vasco. Siguiendo el orden jerárquico estricto del proyecto de construcción de la mayor y más rigurosa Base de Datos de Destinos de España, habiendo recorrido en orden alfabético global las Comunidades Autónomas de Andalucía, Aragón, Principado de Asturias, Islas Baleares, Canarias, Cantabria, Castilla-La Mancha, Castilla y León, Cataluña, Extremadura, Galicia, La Rioja, Comunidad de Madrid, Región de Murcia, Comunidad Foral de Navarra y País Vasco: La última Comunidad Autónoma por procesar en orden alfabético estricto de España es el Principado de Asturias (ya auditada previamente en el proyecto). Al haber cubierto todas las autonomías con actividad costera, monumental e interior regulada de relevancia turística nacional pet-friendly:. Normativa: Normas de uso de arenales restringen el acceso canino a la Playa de Zarautz (la más larga del País Vasco) durante la temporada estival alta (junio a septiembre), permitiéndose el libre esparcimiento y baño sin correa exclusivamente fuera de la temporada oficial (del 1 de octubre al 31 de mayo). Prohibida terminantemente la entrada de animales al área de dunas del Biotopo de Iñurritza por conservación medioambiental. Sanciones de hasta 300 € por negligencias higiénicas.','inventario_turismo_mascotas_pdf');
